function safeGet(key,fallback=null){try{let v=localStorage.getItem(key);return v===null?fallback:v}catch(_){return fallback}}
function safeRemove(key){try{localStorage.removeItem(key)}catch(_){}}
function storageKeys(){let out=[];try{for(let i=0;i<localStorage.length;i++){let k=localStorage.key(i);if(k)out.push(k)}}catch(_){}return out}
function pruneHttpStorage(){let now=Date.now(),rows=[];for(const k of storageKeys()){if(!k.startsWith('mrmHttp'))continue;try{let raw=localStorage.getItem(k),p=raw&&JSON.parse(raw);if(!p||!Number.isFinite(p.ts)||now-p.ts>7*24*60*60*1000){safeRemove(k);continue}rows.push({k,ts:p.ts})}catch(_){safeRemove(k)}}rows.sort((a,b)=>b.ts-a.ts);for(const r of rows.slice(MAX_HTTP_CACHE_ITEMS))safeRemove(r.k)}
function cleanupLegacyStorage(){if(!safeGet(SNAPSHOT_KEY)){for(const k of ['lastStateV35111','lastStateV35110','lastStateV35106','lastStateV35105','lastStateV35104','lastStateV35103','lastStateV35102','lastStateV35']){let raw=safeGet(k);if(raw){safeSet(SNAPSHOT_KEY,raw);break}}}if(!safeGet(HISTORY_KEY)){for(const k of ['riskHistoryV35111','riskHistoryV35110','riskHistoryV35106','riskHistoryV35105','riskHistoryV35','riskHistoryV34','riskHistoryV33','riskHistoryV32','riskHistoryV31','riskHistoryV30']){let raw=safeGet(k);if(raw){safeSet(HISTORY_KEY,raw);break}}}for(const k of storageKeys()){if(/^lastStateV(?!35112$)/.test(k)||/^riskHistoryV(?!35112$)/.test(k)||(/^mrmHttp/.test(k)&&!k.startsWith(CACHE_PREFIX)))safeRemove(k)}pruneHttpStorage();safeSet('mrmStorageSchema',STORAGE_SCHEMA,{retryCleanup:false})}
function safeSet(key,value,{retryCleanup=true}={}){try{localStorage.setItem(key,value);return true}catch(e){if(retryCleanup){pruneHttpStorage();for(const k of storageKeys())if(/^lastStateV(?!35112$)/.test(k))safeRemove(k);try{localStorage.setItem(key,value);return true}catch(_){}}return false}}
function hasNativeAgsiSecretStore(){try{return !!(window.Android&&typeof Android.saveAgsiApiKey==='function'&&typeof Android.hasAgsiApiKey==='function'&&typeof Android.clearAgsiApiKey==='function')}catch(_){return false}}
function agsiKeyConfigured(){try{return hasNativeAgsiSecretStore()?!!Android.hasAgsiApiKey():!!safeGet(AGSI_LOCAL_KEY)}catch(_){return !!safeGet(AGSI_LOCAL_KEY)}}
function agsiStorageMode(){return hasNativeAgsiSecretStore()?'ANDROID_KEYSTORE':'WEBVIEW_LOCAL'}
function agsiValidateKey(raw){let k=String(raw||'').trim();return k.length>=16&&k.length<=256&&!/\s/.test(k)}
function agsiInvalidateCaches(){try{for(const k of [...responseCache.keys()])if(String(k).includes('agsi.gie.eu'))responseCache.delete(k)}catch(_){}for(const k of storageKeys()){if(k.startsWith(AGSI_LOCAL_CACHE_PREFIX)){safeRemove(k);continue}if(!k.startsWith('mrmHttp'))continue;try{let p=JSON.parse(safeGet(k)||'null');if(p&&String(p.url||'').includes('agsi.gie.eu'))safeRemove(k)}catch(_){}}if(typeof commodityV19!=='undefined'&&commodityV19.euGas){commodityV19.euGas.status='idle';commodityV19.euGas.data=null;commodityV19.euGas.error='';commodityV19.euGas.promise=null;commodityV19.euGas.loadedAt=0}if(typeof commodityV37!=='undefined'&&commodityV37.facilities){commodityV37.facilities.status='idle';commodityV37.facilities.data=null;commodityV37.facilities.error='';commodityV37.facilities.promise=null;commodityV37.facilities.loadedAt=0;commodityV37.facilities.diag=null;commodityV37.history={}}if(typeof commodityV40!=='undefined'&&commodityV40.euGasCountries){commodityV40.euGasCountries.status='idle';commodityV40.euGasCountries.data=null;commodityV40.euGasCountries.error='';commodityV40.euGasCountries.promise=null;commodityV40.euGasCountries.loadedAt=0;commodityV40.euGasCountries.diag=null}}
function agsiSaveKey(raw){let k=String(raw||'').trim();if(!agsiValidateKey(k))return false;let ok=false;try{if(hasNativeAgsiSecretStore())ok=!!Android.saveAgsiApiKey(k);else ok=safeSet(AGSI_LOCAL_KEY,k)}catch(_){ok=false}if(ok)agsiInvalidateCaches();return ok}
function agsiClearKey(){try{if(hasNativeAgsiSecretStore())Android.clearAgsiApiKey();else safeRemove(AGSI_LOCAL_KEY)}catch(_){safeRemove(AGSI_LOCAL_KEY)}agsiInvalidateCaches();return true}
function agsiFallbackKey(){return hasNativeAgsiSecretStore()?null:safeGet(AGSI_LOCAL_KEY)}

function nativeLoadSnapshot(){try{if(window.Android&&typeof Android.loadLatestSnapshot==='function'){let raw=Android.loadLatestSnapshot();if(raw)return JSON.parse(raw)}}catch(_){}return null}
function loadSnapshot(){let n=nativeLoadSnapshot();if(n)return n;for(const k of [SNAPSHOT_KEY,'lastStateV35111','lastStateV35106','lastStateV35104','lastStateV35103','lastStateV35102','lastStateV35']){let raw=safeGet(k);if(!raw)continue;try{return JSON.parse(raw)}catch(_){safeRemove(k)}}return null}
function persistSnapshotSafely(snap){let raw=JSON.stringify(snap);try{if(window.Android&&typeof Android.persistSnapshot==='function')Android.persistSnapshot(raw)}catch(_){}return safeSet(SNAPSHOT_KEY,raw)}
function cacheHash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(36)}
function providerTtl(url){let p=providerFromUrl(url);if(p==='Yahoo Finance')return SMART_REFRESH.market;if(p==='Cboe')return SMART_REFRESH.cboe;if(p==='Zagreb Stock Exchange')return SMART_REFRESH.zse;if(p==='World Bank')return SMART_REFRESH.worldBank;if(p==='IMF')return SMART_REFRESH.imf;if(p==='CFTC')return SMART_REFRESH.cftc;if(p==='ECB')return SMART_REFRESH.ecb;if(p==='OFR')return SMART_REFRESH.ofr;if(p==='US Treasury Fiscal Data')return SMART_REFRESH.treasury;if(p==='New York Fed')return SMART_REFRESH.newYorkFed;if(p==='EIA')return SMART_REFRESH.eia;if(p==='US Department of Energy')return SMART_REFRESH.doe;if(p==='World Gold Council')return SMART_REFRESH.wgc;if(p==='FAO')return 7*24*60*60*1000;if(p==='GIE')return 6*60*60*1000;if(p==='Eurostat')return 5*24*60*60*1000;if(p==='FRED'){let mm=String(url).match(/[?&]id=([^&]+)/),id=mm?decodeURIComponent(mm[1]):'';let k=fredKind(id);return k==='market'?SMART_REFRESH.fredMarket:k==='weekly'?SMART_REFRESH.fredWeekly:SMART_REFRESH.fredMonthly}return SMART_REFRESH.default}
function cachePersistent(url,ttl){let p=providerFromUrl(url);return ttl>=30*60*1000&&!['Yahoo Finance','Cboe','Zagreb Stock Exchange'].includes(p)}
function readHttpCache(url,type,allowStale=false){let key=type+'|'+url,now=Date.now(),ttl=providerTtl(url),x=responseCache.get(key);if(x&&(allowStale||now-x.ts<ttl))return{...x,age:now-x.ts,source:'memory'};if(cachePersistent(url,ttl)){try{let raw=safeGet(CACHE_PREFIX+cacheHash(key));if(raw){let p=JSON.parse(raw);if(p&&p.url===url&&p.type===type&&(allowStale||now-p.ts<ttl)){responseCache.set(key,p);return{...p,age:now-p.ts,source:'persistent'}}}}catch(_){}}return null}
function writeHttpCache(url,type,data){let key=type+'|'+url,p={url,type,ts:Date.now(),data};responseCache.set(key,p);let ttl=providerTtl(url);if(cachePersistent(url,ttl)){try{let raw=JSON.stringify(p);if(raw.length<=180000){safeSet(CACHE_PREFIX+cacheHash(key),raw);pruneHttpStorage()}}catch(_){}}}
function recordProviderCache(url,age,stale=false){let name=providerFromUrl(url),p=providerHealth[name]||(providerHealth[name]={success:0,fail:0,cache:0,lastOk:null,lastError:'',latency:null,lastUrl:''});p.cache=(p.cache||0)+1;p.lastCache=new Date().toISOString();p.cacheAge=age;p.cacheStale=!!stale;p.lastUrl=url;return name}
