 let median1m=medianNumber(ready.map(x=>x.r.m1)),median3m=medianNumber(ready.map(x=>x.r.m3)),mega3=medianNumber(ready.filter(x=>SP500_MEGA10.has(x.e.s)).map(x=>x.r.m3)),rest3=medianNumber(ready.filter(x=>!SP500_MEGA10.has(x.e.s)).map(x=>x.r.m3)),leadershipGap=Number.isFinite(mega3)&&Number.isFinite(rest3)?mega3-rest3:null;
 let sectorNames=[...new Set(SP500_FOCUS.map(e=>e.sector))],sectorRows=sectorNames.map(sector=>{let entries=sp500SectorEntries(sector),sb=companyBreadth(entries,{country:'US',industry:sector}),risk=weightedCompanyScore({below50:Number.isFinite(sb.above50)?100-sb.above50:null,negative3m:Number.isFinite(sb.positive3m)?100-sb.positive3m:null,stressed:sb.stressed},{below50:40,negative3m:40,stressed:20});return{sector,b:sb,risk}}).filter(x=>x.b.ready>=Math.min(2,x.b.total)&&Number.isFinite(x.risk));
 let weakSectors=sectorRows.filter(x=>x.risk>=55),weakSectorsPct=sectorRows.length?100*weakSectors.length/sectorRows.length:null,sectorCoverage=sectorNames.length?100*sectorRows.length/sectorNames.length:0;
 let us=appState&&appState.countries&&appState.countries.find(x=>x.code==='US'),idx=(us&&us.metrics)||marketMetrics(appState&&appState.series&&appState.series.US||[]),index3m=idx&&idx.m3,indexDist50=idx&&idx.dist50,headlineVsMedian=Number.isFinite(index3m)&&Number.isFinite(median3m)?index3m-median3m:null;
 let breadth50Risk=Number.isFinite(b.above50)?100-b.above50:null,breadth200Risk=Number.isFinite(b.above200)?100-b.above200:null,medianMomentumRisk=Number.isFinite(median3m)?clamp(50-median3m*6):null,sectorRisk=weakSectorsPct,stressRisk=b.stressed,concentrationRisk=Number.isFinite(leadershipGap)?clamp((leadershipGap-1)*9):null;
 let internal=weightedCompanyScore({breadth50Risk,breadth200Risk,medianMomentumRisk,sectorRisk,stressRisk,concentrationRisk},{breadth50Risk:22,breadth200Risk:12,medianMomentumRisk:20,sectorRisk:18,stressRisk:13,concentrationRisk:15});
