 let score=weightedCompanyScore({internal,divergenceRisk,concentrationRisk,concealment},{internal:45,divergenceRisk:25,concentrationRisk:15,concealment:15}),indexAvailable=idx&&Number.isFinite(index3m),confidence=Math.round(clamp(coverage*.75+sectorCoverage*.15+(indexAvailable?10:0))),regime='INSUFFICIENT DATA';
 if(coverage>=40){if(Number.isFinite(internal)&&internal>=60&&Number.isFinite(concealment)&&concealment<35)regime='WEAKNESS ALREADY VISIBLE';else if(Number.isFinite(score)&&score>=80)regime='SEVERE HIDDEN WEAKNESS';else if(Number.isFinite(score)&&score>=65)regime='HIGH HIDDEN WEAKNESS';else if(Number.isFinite(score)&&score>=45)regime='EARLY DIVERGENCE';else if(Number.isFinite(score)&&score>=25)regime='WATCH';else regime='HEALTHY PARTICIPATION'}
