function dividendValidEvents(divs){return (Array.isArray(divs)?divs:[]).filter(x=>x&&Number.isFinite(Number(x.amount))&&Number(x.amount)>0&&/^\d{4}-\d{2}-\d{2}$/.test(String(x.d||''))).map(x=>({d:String(x.d),amount:Number(x.amount)})).sort((a,b)=>a.d.localeCompare(b.d))}
