function dividendFrequency(events){let e=dividendValidEvents(events);if(e.length<2)return e.length?L('Nedovoljno povijesti','Insufficient history'):L('Nema dividende','No dividend');let gaps=[];for(let i=1;i<e.length;i++){let d=(new Date(e[i].d+'T00:00:00Z')-new Date(e[i-1].d+'T00:00:00Z'))/86400000;if(Number.isFinite(d)&&d>5&&d<500)gaps.push(d)}let g=dividendMedian(gaps.slice(-8));if(!Number.isFinite(g))return L('Neredovito','Irregular');if(g<45)return L('Mjesečno','Monthly');if(g<125)return L('Kvartalno','Quarterly');if(g<230)return L('Polugodišnje','Semiannual');if(g<430)return L('Godišnje','Annual');return L('Neredovito','Irregular')}
