function dividendCagr(annual,years){let ys=Object.keys(annual||{}).map(Number).filter(Number.isFinite).sort((a,b)=>a-b),end=ys.length?ys[ys.length-1]:null,start=end-years;if(!end||!Number.isFinite(annual[String(start)])||!Number.isFinite(annual[String(end)])||annual[String(start)]<=0||annual[String(end)]<=0)return null;return 100*(Math.pow(annual[String(end)]/annual[String(start)],1/years)-1)}
function dividendHistoryStats(events,price=null){let e=dividendValidEvents(events),now=Date.now(),cutoff=now-366*86400000,ttm=e.filter(x=>new Date(x.d+'T00:00:00Z').getTime()>=cutoff),ttmAmount=ttm.reduce((s,x)=>s+x.amount,0),ttmYield=Number.isFinite(price)&&price>0&&ttmAmount>0?100*ttmAmount/price:null,annualAll=dividendAnnualTotals(e),currentYear=new Date().getUTCFullYear(),annual=Object.fromEntries(Object.entries(annualAll).filter(([y])=>Number(y)<currentYear)),years=Object.keys(annual).map(Number).sort((a,b)=>a-b),cuts=[],growthYears=0,noCutYears=0;for(let i=1;i<years.length;i++){let p=annual[String(years[i-1])],c=annual[String(years[i])],chg=p>0?100*(c/p-1):null;if(Number.isFinite(chg)&&chg<=-10)cuts.push({year:years[i],change:chg});}
 for(let i=years.length-1;i>0;i--){let p=annual[String(years[i-1])],c=annual[String(years[i])];if(p>0&&c>p*1.005)growthYears++;else break}
 for(let i=years.length-1;i>0;i--){let p=annual[String(years[i-1])],c=annual[String(years[i])];if(p>0&&c>=p*.90)noCutYears++;else break}
 let latest=e.length?e[e.length-1]:null,freq=dividendFrequency(e),cagr3=dividendCagr(annual,3),cagr5=dividendCagr(annual,5),lastDate=latest?new Date(latest.d+'T00:00:00Z').getTime():null,daysSince=Number.isFinite(lastDate)?Math.max(0,(now-lastDate)/86400000):null,gaps=[];for(let i=1;i<e.length;i++)gaps.push((new Date(e[i].d+'T00:00:00Z')-new Date(e[i-1].d+'T00:00:00Z'))/86400000);let medGap=dividendMedian(gaps.filter(x=>x>5&&x<500).slice(-8)),possibleSuspension=Number.isFinite(daysSince)&&Number.isFinite(medGap)&&e.length>=3&&daysSince>Math.max(120,medGap*1.9),coverage=Math.min(100,Math.round((Math.min(5,years.length)/5)*70+Math.min(4,e.length)/4*30));return{payer:e.length>0,events:e,ttmAmount:ttmAmount||null,ttmYield,ttmCount:ttm.length,latest,frequency:freq,annual,cagr3,cagr5,growthYears,noCutYears,cuts,lastCut:cuts.length?cuts[cuts.length-1]:null,possibleSuspension,daysSince,medianGapDays:medGap,coverage}}
function dividendSafety(rec){let m=rec&&rec.metrics||{},d=dividendHistoryStats(rec&&rec.meta&&rec.meta.dividends,m.value);if(!d.payer)return{score:null,coverage:d.coverage,label:L('Nema dividende','No dividend'),parts:{},data:d};let cutSafety=d.cuts.length===0?95:d.cuts.length===1?62:d.cuts.length===2?38:20;if(d.possibleSuspension)cutSafety=Math.min(cutSafety,25);let growth=Number.isFinite(d.cagr5)?clamp(60+d.cagr5*4,15,100):Number.isFinite(d.cagr3)?clamp(58+d.cagr3*4,15,100):d.growthYears>=2?78:60,consistency=clamp(55+d.noCutYears*9+(d.ttmCount>=3?10:0),25,100),market=Number.isFinite(m.coreRisk)?100-m.coreRisk:Number.isFinite(m.draw52)?100-companyDrawdownRisk(m.draw52):null,yieldQuality=Number.isFinite(d.ttmYield)?(d.ttmYield>12?25:d.ttmYield>8?45:d.ttmYield>5?70:d.ttmYield>=1?90:82):null,parts={history:cutSafety,growth,consistency,market,yieldQuality},score=weightedCompanyScore(parts,{history:30,growth:20,consistency:20,market:20,yieldQuality:10}),label=!Number.isFinite(score)?'N/A':score>=80?L('VISOKA','HIGH'):score>=65?L('DOBRA','GOOD'):score>=45?L('UMJERENA','MODERATE'):L('NISKA','LOW');return{score,coverage:d.coverage,label,parts,data:d}}
