function industryThemeKey(x){let s=((x&&x.id)||'')+' '+((x&&x.name)||'');s=s.toUpperCase();if(/SEMICONDUCT/.test(s))return'SEMICONDUCTORS';if(/BANK/.test(s))return'BANKS';if(/INSURANCE/.test(s))return'INSURANCE';if(/PHARMA|HEALTH|MEDIC/.test(s))return'HEALTH';if(/AUTO/.test(s))return'AUTO';if(/DEFEN/.test(s))return'DEFENSE';if(/CHEM/.test(s))return'CHEMICALS';if(/MINING|FOREST|MATERIAL/.test(s))return'MATERIALS';if(/REAL ESTATE|PROPERTY/.test(s))return'REAL_ESTATE';if(/CONSTRUCTION|INFRA/.test(s))return'CONSTRUCTION';if(/TOURISM|LUXURY/.test(s))return s.includes('LUXURY')?'LUXURY':'TOURISM';if(/TRANSPORT|LOGISTIC|AEROSPACE/.test(s))return'TRANSPORT';if(/TELECOM/.test(s))return'TELECOM';if(/COMMUNICATION/.test(s))return'COMMUNICATION';if(/SOFTWARE|TECH/.test(s))return'TECH';if(/RENEW|WIND/.test(s))return'RENEWABLES';if(/UTILITY|UTILITIES/.test(s))return'UTILITIES';if(/ENERGY|REFIN/.test(s))return'ENERGY';if(/FOOD|STAPLE/.test(s))return'STAPLES_FOOD';if(/CONSUMER|RETAIL/.test(s))return'CONSUMER';if(/FINANC/.test(s))return'FINANCIALS';if(/INDUSTR/.test(s))return'INDUSTRIALS';return'INDUSTRIALS'}
