function companyContextRisk(entry,context={}){let r=companySummaries[entry.s];if(!r||r.status!=='ready')return{score:null,core:null,countryRelative:null,industryRelative:null,relative:companyRelativeStrength(entry,context)};let rel=companyRelativeStrength(entry,context),core=Number.isFinite(r.coreRisk)?r.coreRisk:r.risk,countryRelative=adverseMomentumRisk(rel.m3Country),industryRelative=adverseMomentumRisk(rel.m3Industry),score=weightedCompanyScore({core,countryRelative,industryRelative},{core:70,countryRelative:15,industryRelative:15});return{score,core,countryRelative,industryRelative,relative:rel}}
function companyBreadth(entries,context={}){let query=(entries||[]).filter(e=>e&&e.q!==false),ready=query.map(e=>({e,r:companySummaries[e.s]})).filter(x=>x.r&&x.r.status==='ready'),coverage=query.length?Math.round(100*ready.length/query.length):0,pctMetric=fn=>{let vals=ready.map(fn).filter(v=>v===true||v===false);return vals.length?100*vals.filter(Boolean).length/vals.length:null},above50=pctMetric(x=>Number.isFinite(x.r.dist50)?x.r.dist50>0:null),above200=pctMetric(x=>Number.isFinite(x.r.dist200)?x.r.dist200>0:null),positive1m=pctMetric(x=>Number.isFinite(x.r.m1)?x.r.m1>0:null),positive3m=pctMetric(x=>Number.isFinite(x.r.m3)?x.r.m3>0:null),outCountry=pctMetric(x=>{let v=companyRelativeStrength(x.e,context).m3Country;return Number.isFinite(v)?v>0:null}),outIndustry=pctMetric(x=>{let v=companyRelativeStrength(x.e,context).m3Industry;return Number.isFinite(v)?v>0:null}),risks=ready.map(x=>companyContextRisk(x.e,context).score).filter(Number.isFinite),stressed=risks.length?100*risks.filter(v=>v>=60).length/risks.length:null,avgRisk=risks.length?avg(risks):null,parts={below50:Number.isFinite(above50)?100-above50:null,below200:Number.isFinite(above200)?100-above200:null,negative1m:Number.isFinite(positive1m)?100-positive1m:null,negative3m:Number.isFinite(positive3m)?100-positive3m:null,underCountry:Number.isFinite(outCountry)?100-outCountry:null,underIndustry:Number.isFinite(outIndustry)?100-outIndustry:null,stressed},score=weightedCompanyScore(parts,{below50:17,below200:13,negative1m:18,negative3m:20,underCountry:12,underIndustry:10,stressed:10}),confidence=query.length===0?'N/A':coverage>=80?'HIGH':coverage>=50?'MEDIUM':'LOW';return{score,coverage,confidence,total:query.length,ready:ready.length,above50,above200,positive1m,positive3m,outCountry,outIndustry,stressed,avgRisk}}
function breadthMiniHtml(b,mode='country'){if(!b||!b.total)return `<div class="breadth-card"><div><b>${esc(L('Company Breadth','Company Breadth'))}</b><span>${esc(L('Nema pouzdanog live feeda za ovu listu.','No reliable live feed is available for this list.'))}</span></div><div>${statusPill(null)} N/A</div></div>`;let rel=mode==='industry'?b.outIndustry:b.outCountry;return `<div class="breadth-card"><div class="breadth-head"><div><b>${esc(mode==='industry'?L('Industry Company Breadth','Industry Company Breadth'):L('Country Company Breadth','Country Company Breadth'))}</b><span>${esc(L('Širina signala među najvažnijim kompanijama; viši score znači šire slabljenje.','Signal breadth across key companies; a higher score means broader deterioration.'))}</span></div><div>${statusPill(b.score)} <b>${Number.isFinite(b.score)?Math.round(b.score)+'/100':'N/A'}</b></div></div><div class="breadth-grid"><span><b>${Number.isFinite(b.above50)?fmt(b.above50,0)+'%':'N/A'}</b>${esc(L('iznad 50DMA','above 50DMA'))}</span><span><b>${Number.isFinite(b.positive3m)?fmt(b.positive3m,0)+'%':'N/A'}</b>${esc(L('pozitivno 3M','positive 3M'))}</span><span><b>${Number.isFinite(rel)?fmt(rel,0)+'%':'N/A'}</b>${esc(mode==='industry'?L('nadmašuje industriju 3M','outperform industry 3M'):L('nadmašuje indeks 3M','outperform index 3M'))}</span><span><b>${Number.isFinite(b.stressed)?fmt(b.stressed,0)+'%':'N/A'}</b>${esc(L('u stresu','stressed'))}</span><span><b>${b.ready}/${b.total}</b>${esc(L('pokrivenost','coverage'))} · ${esc(b.confidence)}</span></div></div>`}
