function stockRiskMeaning(score){if(!Number.isFinite(score))return L('Nema dovoljno podataka za pouzdanu procjenu rizika dionice.','Not enough data for a reliable stock-risk assessment.');if(score>=75)return L('Dionica pokazuje vrlo visok kombinirani trend, drawdown, volatilnost i relativni stres. To nije automatski signal za prodaju, ali zahtijeva dodatnu provjeru.','The stock shows very high combined trend, drawdown, volatility and relative stress. This is not an automatic sell signal, but it warrants additional review.');if(score>=60)return L('Rizik je povišen i više signala potvrđuje slabljenje. Važno je usporediti ga s lokalnim indeksom i industrijom.','Risk is elevated and several signals confirm deterioration. Compare it with the local index and industry.');if(score>=45)return L('Dionica je u zoni opreza; smjer i relativna snaga važniji su od samog jednog dnevnog pomaka.','The stock is in a caution zone; direction and relative strength matter more than a single daily move.');return L('Dostupni tržišni signali trenutačno ne pokazuju širok stres u ovoj dionici.','Available market signals currently do not show broad stress in this stock.')}
