function clamp(v,a=0,b=100){return Math.max(a,Math.min(b,v))}
function avg(a){let x=a.filter(Number.isFinite);return x.length?x.reduce((s,v)=>s+v,0)/x.length:null}
function std(a){let x=a.filter(Number.isFinite);if(x.length<2)return null;let m=avg(x);return Math.sqrt(x.reduce((s,v)=>s+(v-m)*(v-m),0)/(x.length-1))}
