const FRED_RELEASE_RULES_V49={NFCI:{nextLagDays:12},NFCIRISK:{nextLagDays:12},NFCICREDIT:{nextLagDays:12},NFCILEVERAGE:{nextLagDays:12},NFCINONFINLEVERAGE:{nextLagDays:12},STLFSI4:{nextLagDays:12},DPSACBW027SBOG:{nextLagDays:16}};
