function normalizeFrequencyV49(kind){let x=String(kind||'').toLowerCase();if(x==='market')return'daily';if(['daily','weekly','monthly','quarterly','annual','event'].includes(x))return x;if(x==='macro')return'unknown';return x||'unknown'}
function fredFrequencyV49(id,fallback='unknown'){return FRED_FREQUENCY_V49[String(id||'').toUpperCase()]||normalizeFrequencyV49(fallback)}
function fredSeriesIdV49(e){if(!e)return'';if(e.seriesId)return String(e.seriesId).toUpperCase();if(e.id)return String(e.id).toUpperCase();let u=String(e.sourceUrl||'');let m=u.match(/[?&]id=([^&]+)/i);if(m)return decodeURIComponent(m[1]).toUpperCase();m=String(e.source||'').match(/(?:FRED|via FRED)\s+([A-Z0-9][A-Z0-9._-]*)/i);return m?m[1].toUpperCase():''}
function freshnessModelV49({observationDate=null,retrievedAt=null,frequency='unknown',provider='',seriesId='',releaseDate=null,expectedNextRelease=null,nowMs=Date.now()}={}){let f=normalizeFrequencyV49(frequency),raw=String(observationDate||''),d=new Date(raw?(raw.length<=10?raw.slice(0,10)+'T23:59:59Z':raw):'');if(!raw||Number.isNaN(d.getTime()))return{observationDate:observationDate||null,retrievedAt:retrievedAt||null,frequency:f,releaseDate:releaseDate||null,expectedNextRelease:expectedNextRelease||null,observationAge:null,observationAgeDays:null,releaseStatus:'UNKNOWN',freshnessStatus:'UNKNOWN'};let ageDays=Math.max(0,(nowMs-d.getTime())/86400000),id=String(seriesId||'').toUpperCase(),rule=FRED_RELEASE_RULES_V49[id]||null,next=expectedNextRelease||(rule&&rule.nextLagDays!=null?addUtcDaysV49(raw,rule.nextLagDays):null),nextMs=next?new Date(next+'T23:59:59Z').getTime():NaN,status='UNKNOWN',releaseStatus='UNKNOWN';if(Number.isFinite(nextMs)){let overdue=(nowMs-nextMs)/86400000;if(overdue<=0){status=(f==='quarterly'||f==='annual')?'OLD_BUT_CURRENT_RELEASE':'CURRENT';releaseStatus='LATEST_EXPECTED_RELEASE'}else if(overdue<=2){status='LATE';releaseStatus='EXPECTED_RELEASE_DUE'}else{status='STALE';releaseStatus='EXPECTED_NEWER_RELEASE'}}else if(f==='quarterly'||f==='annual'){status='OLD_BUT_CURRENT_RELEASE';releaseStatus='LATEST_AVAILABLE_PROVIDER_SCHEDULE_UNKNOWN'}else if(f==='monthly'){status=ageDays<=75?'OLD_BUT_CURRENT_RELEASE':ageDays<=120?'LATE':'UNKNOWN';releaseStatus=ageDays<=75?'LATEST_AVAILABLE_PROVIDER_SCHEDULE_UNKNOWN':ageDays<=120?'CADENCE_LATE_SCHEDULE_UNKNOWN':'UNKNOWN'}else if(f==='weekly'){status=ageDays<=14?'CURRENT':ageDays<=21?'LATE':'STALE';releaseStatus=status==='CURRENT'?'CADENCE_CURRENT':status==='LATE'?'CADENCE_LATE':'CADENCE_STALE'}else if(f==='daily'){status=ageDays<=4?'CURRENT':ageDays<=7?'LATE':'STALE';releaseStatus=status==='CURRENT'?'CADENCE_CURRENT':status==='LATE'?'CADENCE_LATE':'CADENCE_STALE'}else if(f==='event'){status='UNKNOWN';releaseStatus='EVENT_DRIVEN'}return{observationDate:raw.slice(0,10),retrievedAt:retrievedAt||null,frequency:f,releaseDate:releaseDate||null,expectedNextRelease:next||null,observationAge:Math.round(ageDays*10)/10,observationAgeDays:Math.round(ageDays*10)/10,releaseStatus,freshnessStatus:status}}
