function equityMeaning(eq){if(!eq||!Number.isFinite(eq.score))return L('Nema dovoljno market-internals podataka.','Insufficient market-internals data.');if(eq.regime==='HIDDEN EQUITY DETERIORATION')return L('Headline indeks još ne izgleda izrazito loše, ali breadth, leadership, size participation ili options tržište pokazuju znatno veći stres. To povećava fragilnost ako vodeće dionice oslabe.','The headline index does not yet look severely stressed, but breadth, leadership, size participation or options markets show materially more stress. Fragility rises if current leaders weaken.');if(eq.regime==='BROAD EQUITY STRESS')return L('Slabost je široka i potvrđena kroz više market-internals kategorija. Ovo je ozbiljnije od izoliranog pada nekoliko velikih dionica.','Weakness is broad and confirmed across several market-internals categories. This is more serious than an isolated decline in a few large stocks.');if(eq.regime==='INTERNALS WEAKENING')return L('Participacija i unutarnja kvaliteta tržišta slabe. Još nema široko potvrđenog equity stresa, ali treba pratiti breadth i relativnu snagu manjih/sekundarnih indeksa.','Participation and internal market quality are weakening. Broad equity stress is not yet confirmed, but breadth and relative strength of smaller/secondary indexes deserve attention.');return L('Market internals zasad potvrđuju relativno zdravo ili mješovito tržišno sudjelovanje.','Market internals currently confirm relatively healthy or mixed participation.')}
function drawMarketCharts(code,range=252){let c=appState.countries.find(x=>x.code===code),eq=appState.equity&&appState.equity.byCode&&appState.equity.byCode[code];if(!c)return;let main=(c.series||appState.series[code]||[]).slice(-range);drawLineChart($('marketPriceChart'),[{name:c.index,data:main}],{decimals:c.metrics&&c.metrics.value>1000?0:1});if(eq){let defs=[{name:c.index,data:normalizeWindow(c.series||appState.series[code],range)}],aux=eq.aux||{};(aux.equalWeight?[aux.equalWeight]:aux.secondary||[]).slice(0,2).forEach((ss,i)=>defs.push({name:i===0?(code==='DE'?'MDAX / secondary':'Equal-weight / secondary'):'Secondary '+(i+1),data:normalizeWindow(ss,range)}));if(aux.smallCap)defs.push({name:'Small cap',data:normalizeWindow(aux.smallCap,range)});drawLineChart($('marketRelativeChart'),defs,{decimals:1});if($('marketRelativeLegend'))$('marketRelativeLegend').innerHTML=defs.filter(d=>d.data&&d.data.length).map((d,i)=>`<span><i class="legend-dot" style="background:${linePalette(i)}"></i>${esc(d.name)}</span>`).join('');if(code==='US'&&aux.options){let o=aux.options,od=[];if(o.vix)od.push({name:'VIX',data:normalizeWindow(o.vix,range)});if(o.vix3m)od.push({name:'VIX3M',data:normalizeWindow(o.vix3m,range)});if(o.vvix)od.push({name:'VVIX',data:normalizeWindow(o.vvix,range)});drawLineChart($('marketOptionsChart'),od,{decimals:1});if($('marketOptionsLegend'))$('marketOptionsLegend').innerHTML=od.filter(d=>d.data&&d.data.length).map((d,i)=>`<span><i class="legend-dot" style="background:${linePalette(i)}"></i>${esc(d.name)}</span>`).join('')}}}

function volRisk(rv){if(!Number.isFinite(rv))return null;if(rv<14)return 15;if(rv<20)return 30;if(rv<28)return 55;if(rv<40)return 75;return 92}
function trendRisk(m){if(!m)return null;let parts=[];if(Number.isFinite(m.dist200))parts.push(m.dist200>=3?12:m.dist200>=0?25:m.dist200>=-5?55:clamp(72+(-m.dist200-5)*3));if(Number.isFinite(m.draw52))parts.push(m.draw52>-5?18:m.draw52>-10?38:m.draw52>-20?62:clamp(82+(-m.draw52-20)));if(Number.isFinite(m.m3))parts.push(m.m3>=5?15:m.m3>=0?28:m.m3>=-10?55:clamp(75+(-m.m3-10)*2));if(Number.isFinite(m.maCross))parts.push(m.maCross>=0?20:68);return avg(parts)}
function fxRisk(m){if(!m)return null;let vr=volRisk(m.rv20),move=Number.isFinite(m.m3)?clamp(15+Math.abs(m.m3)*4):null;return avg([vr,move])}
function marketRisk(m){return avg([trendRisk(m),volRisk(m&&m.rv20),Number.isFinite(m&&m.draw52)?clamp(20+Math.max(0,-m.draw52)*3):null])}
function macroRiskFromWB(gdp,inf,unemp){let parts=[];if(gdp)parts.push(gdp.value>=3?20:gdp.value>=1?35:gdp.value>=0?55:80);if(inf)parts.push(inf.value>=0&&inf.value<=4?25:inf.value<=7?50:75);if(unemp)parts.push(unemp.value<5?25:unemp.value<8?45:70);return avg(parts)}
function germanyMacroRisk(f){let parts=[];let ip=f.DEUPROINDMISMEI||[];if(ip.length>=4){let ch=pct(ip[ip.length-1].v,ip[Math.max(0,ip.length-4)].v);parts.push(ch>=1?20:ch>=0?35:ch>=-2?60:80)}let hc=f.CP0000DEM086NEST||[];if(hc.length>=13){let yoy=pct(hc[hc.length-1].v,hc[hc.length-13].v);parts.push(yoy>=1&&yoy<=3?22:yoy<=4?42:yoy<=6?62:80)}let ex=f.XTEXVA01DEM659S||[];if(ex.length){let v=ex[ex.length-1].v;parts.push(v>=5?20:v>=0?35:v>=-5?60:80)}let y=f.IRLTLT01DEM156N||[];if(y.length>=4){let bp=(y[y.length-1].v-y[Math.max(0,y.length-4)].v)*100;parts.push(Math.abs(bp)<40?25:Math.abs(bp)<90?50:75)}return avg(parts)}
function usMacroRisk(f){let e=usEarly(f).filter(x=>['Recession','Labor','Yield curve'].includes(x.trend));return avg(e.map(x=>x.score))}
function contributorsForCountry(c){let a=[];const push=(name,score,weight)=>{if(Number.isFinite(score))a.push({name,score,impact:score*weight/100})};let w=getWeights();push('Market stress',c.subscores.market,w.market);push('Macro',c.subscores.macro,w.macro);push('Credit',c.subscores.credit,w.credit);push('Liquidity / FX',c.subscores.liquidity,w.liquidity);push('Valuation',c.subscores.valuation,w.valuation);push('Technical trend',c.subscores.technical,w.technical);push('Systemic',c.subscores.systemic,w.systemic);return a.sort((x,y)=>y.impact-x.impact)}

