function providerHealthHtml(){let entries=Object.entries(providerHealth).sort((a,b)=>((b[1].success+(b[1].cache||0))-(a[1].success+(a[1].cache||0)))||(a[0].localeCompare(b[0])));if(!entries.length)return `<div class="small">${esc(L('Status izvora pojavit će se nakon osvježavanja.','Provider status appears after a refresh.'))}</div>`;return entries.map(([name,p])=>{let total=p.success+p.fail,failRatio=total?p.fail/total:0,onlyCache=!p.success&&(p.cache||0)>0,status=onlyCache?'CACHED':p.success===0?'OFFLINE':failRatio>=.35?'DEGRADED':'ONLINE',cls=status==='ONLINE'?'status-green':status==='CACHED'?'status-limited':status==='DEGRADED'?'status-orange':'status-red',cacheAge=Number.isFinite(p.cacheAge)?Math.round(p.cacheAge/60000):null,meta=[p.lastOk?L('zadnji uspjeh','last success')+' '+new Date(p.lastOk).toLocaleTimeString(locale()):null,Number.isFinite(p.latency)?p.latency+' ms':null,(p.cache||0)?L('cache pogodaka','cache hits')+' '+p.cache+(cacheAge!==null?' · '+cacheAge+' min':''):null,p.fail?L('neuspjeli upiti','failed requests')+' '+p.fail:null].filter(Boolean).join(' · ');return `<div class="provider-row"><div><div class="pname">${esc(name)}</div><div class="pmeta">${esc(meta||p.lastError||'')}</div>${status==='OFFLINE'&&p.lastError?`<div class="pmeta">${esc(p.lastError)}</div>`:''}</div><span class="pill ${cls}">${status}</span></div>`}).join('')}
