function indicatorMeaning(e){if(!e)return L('Nema dovoljno podataka za tumačenje.','Not enough data for an interpretation.');let explicit=currentLang==='hr'?e.meaningHr:e.meaningEn;if(explicit)return explicit;if(!Number.isFinite(e.score))return L('Pouzdan podatak nije dostupan pa se indikator ne uključuje u score.','Reliable data is unavailable, so this indicator is excluded from the score.');let band=riskBand(e.score).label,trend=String(e.trend||'').toLowerCase();let family=trend.includes('credit')?L('kreditnim uvjetima','credit conditions'):trend.includes('fund')?L('financiranju i likvidnosti','funding and liquidity'):trend.includes('vol')?L('tržišnoj volatilnosti','market volatility'):trend.includes('macro')||trend.includes('recession')||trend.includes('labor')?L('makro ciklusu','the macro cycle'):trend.includes('supply')||trend.includes('energy')||trend.includes('commodity')?L('robama i input-costovima','commodities and input costs'):L('širem tržišnom riziku','broader market risk');if(e.score>=75)return L(`Signal je u RED području i ukazuje na neuobičajeno visok stres u ${family}. Važniji je kada ga potvrđuju neovisni indikatori.`,`The signal is in the RED zone and indicates unusually high stress in ${family}. It matters more when independent indicators confirm it.`);if(e.score>=60)return L(`Signal je povišen i upozorava na pogoršanje u ${family}, ali sam nije dovoljan za zaključak o sistemskom događaju.`,`The signal is elevated and warns of deterioration in ${family}, but is not enough by itself to imply a systemic event.`);if(e.score>=45)return L(`Signal je u zoni opreza za ${family}. Potrebno je pratiti smjer i potvrdu drugih indikatora.`,`The signal is in a caution zone for ${family}. Direction and confirmation from other indicators matter.`);return L(`Signal trenutno ne pokazuje neuobičajen stres u ${family}.`,`The signal currently does not show unusual stress in ${family}.`)}
function indicatorExplainHtml(e){let status=Number.isFinite(e.score)?riskBand(e.score).label:'N/A',peers=(appState.early||[]).filter(x=>x!==e&&Number.isFinite(x.score)&&x.score>=60).sort((a,b)=>b.score-a.score).slice(0,3).map(x=>x.name),hist=Number.isFinite(e.percentile)?`P${Math.round(e.percentile)}`:L('nema dovoljne povijesti','insufficient history'),what=e.trend?`${e.name} · ${e.trend}`:e.name;return `<details class="explain-details"><summary>ⓘ ${esc(L('Zašto je važno?','Why does it matter?'))}</summary><div class="explain-grid"><div class="explain-item"><b>${esc(L('ŠTO JE TO?','WHAT IS IT?'))}</b>${esc(what||'N/A')}</div><div class="explain-item"><b>${esc(L('TRENUTNI SIGNAL','CURRENT SIGNAL'))}</b>${esc(status)}${Number.isFinite(e.value)?' · '+esc(fmt(e.value,2)+(e.unit||'')):''}</div><div class="explain-item"><b>${esc(L('ŠTO ZNAČI ZA TRŽIŠTE','MARKET MEANING'))}</b>${esc(indicatorMeaning(e))}</div><div class="explain-item"><b>${esc(L('POTVRDA','CONFIRMATION'))}</b>${esc(peers.length?peers.join(' · '):L('Nema dovoljno neovisnih povišenih signala.','No independent elevated signals currently confirm it.'))}</div><div class="explain-item"><b>${esc(L('POVIJESNI KONTEKST','HISTORICAL CONTEXT'))}</b>${esc(hist)} · ${esc(L('Pouzdanost','Confidence'))}: ${esc(e.confidence||'N/A')} · ${esc(L('Svježina','Freshness'))}: ${esc(e.freshness||freshnessStatus(e.date,e.dataKind||'market',e.provider||'').status)}${e.expectedNextRelease?' · '+esc(L('Sljedeća očekivana objava','Next expected release'))+': '+esc(e.expectedNextRelease):''}${e.releaseStatus&&e.releaseStatus!=='UNKNOWN'?' · '+esc(L('Status objave','Release status'))+': '+esc(e.releaseStatus):''}</div></div></details>`}
function countryMeaning(c){if(!c||!Number.isFinite(c.risk))return L('Za ovo tržište nema dovoljno pouzdanih podataka za kompozitni zaključak.','There is not enough reliable data for a composite conclusion on this market.');if(c.limited||c.eligibleV50===false){let cv=c.coverageV50||{};return L('Numerički score je samo dijagnostički jer tržište ne prolazi minimalni coverage gate.','The numeric score is diagnostic only because this market does not pass the minimum coverage gate.')+' '+L('Efektivna pokrivenost','Effective coverage')+': '+(Number.isFinite(cv.effectiveWeightedCoverage)?cv.effectiveWeightedCoverage+'%':'N/A')+' · '+L('faktorske grupe','factor groups')+': '+(cv.factorGroups??'N/A')+'/'+Object.keys(COUNTRY_FACTOR_GROUPS_V50).length+'.';}let top=(c.contributors||[]).slice(0,3).map(x=>x.name),band=riskBand(c.risk);let base=c.risk>=75?L('Rizik je vrlo visok i više kategorija upućuje na ozbiljan stres.','Risk is very high and several categories point to serious stress.'):c.risk>=60?L('Rizik je povišen; tržište je u risk-off području i treba tražiti potvrdu u kreditu, likvidnosti i makru.','Risk is elevated; the market is in a risk-off zone and confirmation should be sought in credit, liquidity and macro data.'):c.risk>=45?L('Rizik je umjereno povišen. Ovo više odgovara zoni opreza nego potvrđenom sistemskom problemu.','Risk is moderately elevated. This is more consistent with caution than a confirmed systemic problem.'):L('Kompozit trenutno ne pokazuje širok stres, iako pojedinačni indikatori još mogu biti povišeni.','The composite currently does not show broad stress, although individual indicators can still be elevated.');return `${base} ${top.length?L('Glavni doprinosi','Main contributors')+': '+top.join(', ')+'. ':''}${L('Režim','Regime')}: ${band.regime}.`}
function scenarioMeaning(s){if(!s)return L('Nema dovoljno potvrđenih cross-asset signala.','There are not enough confirmed cross-asset signals.');let map={
 'LIQUIDITY STRESS':L('Funding i kreditni signali pogoršavaju se zajedno. To može značiti da problem prelazi iz cijena imovine u dostupnost financiranja, što je sistemski važnije.','Funding and credit signals are deteriorating together. This can mean stress is moving from asset prices into financing availability, which is more systemically important.'),
 'ENERGY SUPPLY SHOCK':L('Nafta/plin i njihova volatilnost rastu zajedno, što je konzistentnije sa supply ili geopolitičkim šokom nego sa čistim padom potražnje.','Oil/gas and their volatility are rising together, which is more consistent with a supply or geopolitical shock than a pure demand slowdown.'),
 'GLOBAL DEMAND DETERIORATION':L('Nafta i industrijski metali slabe dok volatilnost raste. Kombinacija je konzistentna sa slabljenjem globalne potražnje, ali nije sama po sebi recesijski dokaz.','Oil and industrial metals are weakening while volatility rises. The combination is consistent with weaker global demand, but is not recession proof by itself.'),
 'VOLATILITY CONTAGION':L('Volatilnost je istodobno povišena kroz više klasa imovine. To smanjuje diversifikacijski benefit i povećava vjerojatnost zajedničkog makro/liquidity faktora.','Volatility is elevated across several asset classes at once. This reduces diversification benefits and raises the likelihood of a common macro/liquidity factor.'),
 'NORMAL / MIXED SIGNALS':L('Cross-asset signali trenutno nisu dovoljno usklađeni za jedan dominantan stresni režim.','Cross-asset signals are not aligned enough to identify one dominant stress regime.')};return map[s.name]||L('Cross-asset obrazac je detektiran, ali interpretaciju treba potvrditi neovisnim signalima.','A cross-asset pattern is detected, but the interpretation should be confirmed by independent signals.')}
function crossAssetScenario(cross,_fred,countries,corr){let by=Object.fromEntries((cross.indicators||[]).map(x=>[x.name,x])),raw=cross.raw||{},oil=marketMetrics(raw.oil||[]),gas=marketMetrics(raw.gas||[]),copper=marketMetrics(raw.copper||[]),gold=marketMetrics(raw.gold||[]),ovx=by['OVX · Oil volatility'],breadth=by['Cross-Asset Volatility Breadth'],fund=avg([by['SOFR − IORB funding spread']&&by['SOFR − IORB funding spread'].score,by['Commercial paper − T-bill']&&by['Commercial paper − T-bill'].score,by['HYG realized volatility']&&by['HYG realized volatility'].score,by['OFR Financial Stress Index']&&by['OFR Financial Stress Index'].score]),support=[],against=[];let mk=(name,confidence)=>({name,confidence,support,against});if(Number.isFinite(fund)&&fund>=65){support=['USD funding/credit composite elevated'];if(by['HYG realized volatility']&&by['HYG realized volatility'].score>=60)support.push('high-yield volatility elevated');if(by['OFR Financial Stress Index']&&by['OFR Financial Stress Index'].score>=60)support.push('OFR systemic stress elevated');return mk('LIQUIDITY STRESS',support.length>=2?'HIGH':'MEDIUM')}if(ovx&&ovx.score>=60&&oil&&oil.m1>3&&gas&&gas.m1>3){support=['OVX elevated','oil rising','natural gas rising'];if(gold&&gold.m1>0)support.push('gold firm');return mk('ENERGY SUPPLY SHOCK',support.length>=3?'HIGH':'MEDIUM')}let cg=by['Copper / Gold ratio'];if(ovx&&ovx.score>=60&&oil&&oil.m1<0&&copper&&copper.m1<0&&cg&&cg.score>=50){support=['OVX elevated','oil falling','copper falling','Copper/Gold weakening'];return mk('GLOBAL DEMAND DETERIORATION','HIGH')}if(breadth&&breadth.score>=60){support=['cross-asset volatility breadth elevated'];if(Number.isFinite(corr&&corr.average)&&corr.average>.55)support.push('cross-market correlation elevated');return mk('VOLATILITY CONTAGION',support.length>=2?'HIGH':'MEDIUM')}return {name:'NORMAL / MIXED SIGNALS',confidence:'MEDIUM',support:[],against:['no single cross-asset stress pattern has enough independent confirmation']}}
