function realizedVolIndicator(name,s,source,meaningHr,meaningEn){let meta=sourceMeta(s),rv=rollingRealizedVol(s,20);if(rv.length<30)return{name,value:null,unit:'%',score:null,source,sourceUrl:meta.url||null,date:null,trend:'Credit volatility',meaningHr,meaningEn,note:'Insufficient history; excluded from score.'};let x=rv[rv.length-1],p=percentileRank(rv.slice(-756).map(q=>q.v),x.v);return{name,value:x.v,unit:'%',score:percentileRisk(p),source:meta.sourceDetail||source,sourceUrl:meta.url||null,provider:meta.source||'',dataKind:'market',date:x.d,trend:'Credit volatility',percentile:p,meaningHr,meaningEn}}
function alignRatio(a,b){let B=new Map((b||[]).map(x=>[x.d,x.v])),out=[];for(const x of a||[])if(B.has(x.d)&&x.v>0&&B.get(x.d)>0)out.push({d:x.d,v:x.v/B.get(x.d)});return out}
async function ecbSeries(dataset,key){let n=dataset==='CLIFS'?240:420,base=`https://data-api.ecb.europa.eu/service/data/${dataset}/${key}`,urls=[`${base}?format=csvdata&detail=dataonly&lastNObservations=${n}`,`${base}?format=csvdata&lastNObservations=${Math.min(n,120)}`],lastErr=null,started=performance.now();for(const u of urls){try{let text=await fetchWithTimeout(u,'text',18000,false),lines=text.trim().split(/\r?\n/);if(lines.length<2)throw new Error('Empty ECB CSV');let h=csvCells(lines[0]),di=h.indexOf('TIME_PERIOD'),vi=h.indexOf('OBS_VALUE'),out=[];for(const line of lines.slice(1)){let p=csvCells(line),v=Number(p[vi]);if(di>=0&&vi>=0&&p[di]&&Number.isFinite(v))out.push({d:String(p[di]).slice(0,10),v})}if(!out.length)throw new Error('No ECB observations');recordProvider(u,true,Math.round(performance.now()-started));return attachMeta(out,{source:'ECB',sourceDetail:`ECB ${dataset} ${key}`,url:u,retrievedAt:new Date().toISOString(),kind:dataset==='CLIFS'?'monthly':'market',confidence:'HIGH'})}catch(e){lastErr=e}}recordProvider(urls[0],false,Math.round(performance.now()-started),(lastErr&&lastErr.message)||'ECB unavailable');return[]}
async function ofrFsi(){let urls=['https://www.financialresearch.gov/financial-stress-index/files/fsi.csv','https://www.financialresearch.gov/financial-stress-index/data/fsi.csv','https://www.financialresearch.gov/files/fsi.csv'],started=performance.now(),lastErr=null;for(const u of urls){try{let text=await fetchWithTimeout(u,'text',12000,false),lines=text.trim().split(/\r?\n/);if(lines.length<2)continue;let h=csvCells(lines[0]),di=h.findIndex(x=>/date/i.test(x)),vi=h.findIndex(x=>/fsi|financial stress/i.test(x));if(vi<0)vi=1;let out=[];for(const line of lines.slice(1)){let p=csvCells(line),v=Number(p[vi]);if(p[di>=0?di:0]&&Number.isFinite(v))out.push({d:String(p[di>=0?di:0]).slice(0,10),v})}if(out.length>10){recordProvider(u,true,Math.round(performance.now()-started));return attachMeta(out,{source:'OFR',sourceDetail:'OFR Financial Stress Index',url:u,retrievedAt:new Date().toISOString(),kind:'market',confidence:'HIGH'})}}catch(e){lastErr=e}}recordProvider(urls[0],false,Math.round(performance.now()-started),(lastErr&&lastErr.message)||'OFR unavailable');return[]}
async function cftcCrowding(){let api='https://publicreporting.cftc.gov/resource/72hh-3qpy.json?$limit=500&$order=report_date_as_yyyy_mm_dd%20DESC',legacy='https://www.cftc.gov/dea/newcot/f_disagg.txt',started=performance.now(),rows=[];try{let j=await fetchWithTimeout(api,'json',16000,false);if(Array.isArray(j)){for(const r of j){let name=String(r.market_and_exchange_names||r.commodity_name||'').toUpperCase();if(!/(GOLD|SILVER|COPPER|CRUDE OIL)/.test(name))continue;let oi=Number(r.open_interest_all),mmLong=Number(r.m_money_positions_long_all),mmShort=Number(r.m_money_positions_short_all),date=String(r.report_date_as_yyyy_mm_dd||'').slice(0,10);if(Number.isFinite(oi)&&oi>0&&Number.isFinite(mmLong)&&Number.isFinite(mmShort)&&/^\d{4}-\d{2}-\d{2}$/.test(date))rows.push({name,date,net:(mmLong-mmShort)/oi*100})}}if(rows.length)recordProvider(api,true,Math.round(performance.now()-started))}catch(_){}if(!rows.length){try{let text=await fetchWithTimeout(legacy,'text',16000,false),lines=text.trim().split(/\r?\n/);for(const line of lines){let p=csvCells(line);if(p.length<20)continue;let name=(p[0]||'').toUpperCase();if(!/(GOLD|SILVER|COPPER|CRUDE OIL)/.test(name))continue;let oi=Number(String(p[7]||'').replace(/,/g,'')),mmLong=Number(String(p[13]||'').replace(/,/g,'')),mmShort=Number(String(p[14]||'').replace(/,/g,'')),date=String(p[2]||'').slice(0,10);if(Number.isFinite(oi)&&oi>0&&Number.isFinite(mmLong)&&Number.isFinite(mmShort)&&/^\d{4}-\d{2}-\d{2}$/.test(date))rows.push({name,date,net:(mmLong-mmShort)/oi*100})}if(rows.length)recordProvider(legacy,true,Math.round(performance.now()-started))}catch(e){recordProvider(api,false,Math.round(performance.now()-started),e.message)}}if(!rows.length)return null;let latest=rows.map(x=>x.date).sort().at(-1),cur=rows.filter(x=>x.date===latest),extreme=Math.max(...cur.map(x=>Math.abs(x.net))),score=extreme<15?20:extreme<25?45:extreme<35?68:85;return{value:extreme,score,rows:cur,date:latest,sourceUrl:rows.length?api:legacy,confidence:'HIGH'}}
