 let sofr=latestPoint(fredMap.SOFR||[]),iorb=latestPoint(fredMap.IORB||[]);let funding=sofr&&iorb?(sofr.v-iorb.v)*100:null;indicators.push({name:'SOFR − IORB funding spread',value:funding,unit:' bp',score:Number.isFinite(funding)?(funding<=5?20:funding<=15?45:funding<=30?68:88):null,source:'FRED SOFR / IORB',sourceUrl:FRED+'SOFR',provider:'FRED',dataKind:'market',date:sofr&&sofr.d,trend:'USD funding',meaningHr:'Pozitivan i neuobičajeno širok SOFR−IORB spread može signalizirati pritisak na tržišno financiranje u USD. Funding stres je sistemski važniji od običnog skoka equity volatilnosti.',meaningEn:'An unusually wide positive SOFR−IORB spread can signal pressure in USD market funding. Funding stress is more systemically important than an isolated equity-volatility spike.'});
