function structuralVulnerabilityIndicators(f){let out=[],pushCredit=(id,name,hr,en)=>{let r=creditDeviationProxy(f[id]||[]),last=latestPoint(f[id]||[]);out.push({name,value:Number.isFinite(r.gap)?r.gap:null,unit:' pp vs 10y mean',score:r.score,source:'BIS via FRED '+id,sourceUrl:FRED+id,provider:'FRED',dataKind:'macro',date:r.date||last&&last.d,trend:'Structural vulnerability',percentile:r.percentile,meaningHr:hr,meaningEn:en,note:'This is a transparent rolling-mean deviation proxy, not the official BIS HP-filter credit-to-GDP gap.'})};
 pushCredit('QUSPAM770A','US private credit/GDP deviation proxy','Privatni kredit znatno iznad vlastitog dugoročnog prosjeka povećava osjetljivost na rast kamata i pad asset values. Proxy ne pokušava zamijeniti službeni BIS credit gap, nego daje transparentan kontekst.','Private credit materially above its own long-run average increases sensitivity to higher rates and falling asset values. This proxy does not replace the official BIS credit gap; it provides transparent context.');
 pushCredit('QDEPAM770A','Germany private credit/GDP deviation proxy','Povišen privatni kredit u odnosu na vlastitu dugoročnu normu povećava ranjivost njemačkih kućanstava i kompanija na refinancing i ciklički pad.','Private credit above its own long-run norm increases the vulnerability of German households and firms to refinancing pressure and cyclical downturns.');
 for(const [id,name,hr,en] of [
 ['QUSGAM770A','US government credit/GDP vulnerability','Visok i rastući javni dug ne govori kada će tržište pasti, ali povećava rollover i term-premium osjetljivost kada investitori postanu cjenovno osjetljiviji.','High and rising public debt does not time a market decline, but it increases rollover and term-premium sensitivity when investors become more price-sensitive.'],
 ['QDEGAM770A','Germany government credit/GDP vulnerability','Njemački javni dug je strukturni kontekst za Bund supply i fiskalni prostor. Koristi se kao fragility faktor, ne kao kratkoročni bearish signal.','German government debt is structural context for Bund supply and fiscal space. It is used as a fragility factor, not a short-term bearish signal.'],
 ['TDSP','US household debt-service burden','Visok udio obaveznih debt-service plaćanja u raspoloživom dohotku smanjuje kućanstvima buffer protiv gubitka prihoda i viših kamata.','A high share of required debt-service payments in disposable income reduces households’ buffer against income losses and higher rates.']]){let ss=f[id]||[],x=latestPoint(ss),p=x?percentileRank(ss.slice(-160).map(q=>q.v),x.v):null;out.push({name,value:x&&x.v,unit:'%',score:Number.isFinite(p)?percentileRisk(p):null,source:(id.startsWith('Q')?'BIS via ':'')+'FRED '+id,sourceUrl:FRED+id,provider:'FRED',dataKind:'macro',date:x&&x.d,trend:'Structural vulnerability',percentile:p,meaningHr:hr,meaningEn:en})}
 let hp=f.QUSR368BIS||[],hx=latestPoint(hp),absHist=hp.slice(-160).map(x=>Math.abs(x.v)),hpP=hx?percentileRank(absHist,Math.abs(hx.v)):null;out.push({name:'US real house-price cycle',value:hx&&hx.v,unit:'% YoY real',score:Number.isFinite(hpP)?percentileRisk(hpP):null,source:'BIS via FRED QUSR368BIS',sourceUrl:FRED+'QUSR368BIS',provider:'FRED',dataKind:'macro',date:hx&&hx.d,trend:'Structural vulnerability',percentile:hpP,meaningHr:'Ekstremno pozitivan realni rast može signalizirati pregrijavanje, dok duboko negativan rast može signalizirati korekciju. Smjer se mora čitati zajedno s kreditom i debt-service burdenom.','meaningEn':'Extremely positive real house-price growth can signal overheating, while deeply negative growth can signal correction. Direction must be read together with credit and debt-service burden.'});
 let comp=avg(out.map(x=>x.score));out.push({name:'Structural Financial Vulnerability Composite',value:comp,unit:'/100',score:comp,source:'BIS/Fed structural data via FRED',date:out.map(x=>x.date).filter(Boolean).sort().at(-1)||null,trend:'Structural vulnerability',meaningHr:'Ovo je fragility multiplier, ne market-timing signal. Visok rezultat znači da će isti tržišni šok vjerojatnije proizvesti jači kreditni/makro efekt zbog duga, debt-service opterećenja ili property ciklusa.','meaningEn':'This is a fragility multiplier, not a market-timing signal. A high reading means the same market shock is more likely to produce a larger credit/macro effect because of debt, debt-service burden or the property cycle.'});return out}
function adverseLevelPercentile(s,adverse='LOW',lookback=240){if(!s||!s.length)return{value:null,percentile:null,score:null,date:null};let x=s[s.length-1],hist=s.slice(-lookback).map(q=>adverse==='LOW'?-q.v:q.v),cur=adverse==='LOW'?-x.v:x.v,p=percentileRank(hist,cur);return{value:x.v,percentile:p,score:percentileRisk(p),date:x.d}}
function tradeShippingIndicators(f){let out=[];
 let eo=adverseLevelPercentile(f.BSXRLV02DEM086S||[],'LOW',240);out.push({name:'Germany export-order books',value:eo.value,unit:' balance',score:eo.score,source:'OECD via FRED BSXRLV02DEM086S',sourceUrl:FRED+'BSXRLV02DEM086S',provider:'FRED',dataKind:'monthly',date:eo.date,trend:'Trade / shipping',percentile:eo.percentile,meaningHr:'Izvozne narudžbe njemačke industrije često reagiraju prije realiziranog izvoza. Duboko negativan i povijesno ekstreman saldo upozorava na slabiju vanjsku potražnju, posebno za cikličke industrije, strojarstvo, kemiju i automotive.',meaningEn:'German manufacturing export-order books often move before realized exports. A deeply negative and historically extreme balance warns of weaker external demand, especially for cyclical industry, machinery, chemicals and autos.'});
 let ex=f.XTEXVA01DEM659S||[],x=latestPoint(ex),xp=x?percentileRank(ex.slice(-180).map(q=>-q.v),-x.v):null;out.push({name:'Germany export growth YoY',value:x&&x.v,unit:'%',score:Number.isFinite(xp)?percentileRisk(xp):null,source:'OECD via FRED XTEXVA01DEM659S',sourceUrl:FRED+'XTEXVA01DEM659S',provider:'FRED',dataKind:'monthly',date:x&&x.d,trend:'Trade / shipping',percentile:xp,meaningHr:'Slabljenje stvarnog izvoznog rasta potvrđuje da se slabije narudžbe pretvaraju u slabije tokove robe. Signal je važniji kada istodobno zaostaju njemački transport, industrija i automotive.',meaningEn:'Weakening realized export growth confirms that softer orders are turning into softer goods flows. The signal matters more when German transport, industrials and autos also underperform.'});
 let fr=adversePctChangeRisk(f.TSIFRGHT||[],3,'DOWN',180);out.push({name:'Freight Transportation Services Index · 3M',value:Number.isFinite(fr.change)?fr.change:null,unit:'%',score:fr.score,source:'US BTS via FRED TSIFRGHT',sourceUrl:FRED+'TSIFRGHT',provider:'FRED',dataKind:'monthly',date:fr.date,trend:'Trade / shipping',percentile:fr.percentile,meaningHr:'Pad freight activity kroz više mjeseci može potvrditi usporavanje fizičkog toka robe. To nije čisti globalni shipping indeks, pa se koristi kao potvrda uz GSCPI i izvozne narudžbe, ne kao samostalan globalni signal.',meaningEn:'A multi-month decline in freight activity can confirm slowing physical goods flows. It is not a pure global shipping index, so it is used as confirmation alongside GSCPI and export orders rather than as a standalone global signal.'});
 let gs=latestPoint(f.GSCPI||[]),gsScore=gs?(gs.v<.5?20:gs.v<1?45:gs.v<2?68:88):null,comp=avg([eo.score,Number.isFinite(xp)?percentileRisk(xp):null,fr.score,gsScore]);out.push({name:'Global Trade & Shipping Stress Composite',value:comp,unit:'/100',score:comp,source:'Composite: German export orders/growth + freight activity + GSCPI',date:[eo.date,x&&x.d,fr.date,gs&&gs.d].filter(Boolean).sort().at(-1)||null,trend:'Trade / shipping',meaningHr:'Kompozit traži potvrdu između narudžbi, realiziranog izvoza, fizičkog freight toka i supply-chain pritiska. Visok score znači da se vanjskotrgovinski ciklus pogoršava u više neovisnih podataka; za Njemačku je to izravniji rizik, a za Hrvatsku važan kanal kroz europsku potražnju, transport i turizam.',meaningEn:'The composite looks for confirmation across orders, realized exports, physical freight flow and supply-chain pressure. A high score means the external-trade cycle is deteriorating across independent data; it is a direct risk for Germany and an important channel for Croatia through European demand, transport and tourism.'});return out}
function alignedSpreadSeries(country,germany){let G=new Map((germany||[]).map(x=>[x.d,x.v])),out=[];for(const x of country||[])if(G.has(x.d)&&Number.isFinite(x.v)&&Number.isFinite(G.get(x.d)))out.push({d:x.d,v:(x.v-G.get(x.d))*100});return out}
function fragmentationSpreadIndicator(f,id,label){let s=alignedSpreadSeries(f[id]||[],f.IRLTLT01DEM156N||[]);if(!s.length)return{name:label,value:null,unit:' bp',score:null,source:'OECD via FRED '+id+' minus Germany',date:null,trend:'Sovereign fragmentation',meaningHr:'Nema dovoljno usporedivih podataka; indikator se isključuje iz scorea.',meaningEn:'Insufficient comparable data; the indicator is excluded from the score.'};let x=s[s.length-1],positiveHist=s.slice(-180).map(q=>Math.max(0,q.v)),lp=percentileRank(positiveHist,Math.max(0,x.v)),levelScore=x.v<=0?18:percentileRisk(lp),chg=changeShockRisk(s,3,120),widenScore=Number.isFinite(chg.change)&&chg.change>0?chg.score:20,score=avg([levelScore,widenScore]);return{name:label,value:x.v,unit:' bp',score,source:'OECD benchmark yields via FRED',sourceUrl:FRED+id,provider:'FRED',dataKind:'monthly',date:x.d,trend:'Sovereign fragmentation',percentile:lp,change3m:chg.change,meaningHr:'Spread prema njemačkom Bundu mjeri koliko dodatnog prinosa tržište traži za državni rizik unutar europskog sustava. Visoka razina ili brzo širenje može signalizirati fragmentaciju, skuplje financiranje i jači bank-sovereign feedback.',meaningEn:'The spread versus German Bunds measures the extra yield investors demand for sovereign risk within Europe. A high level or rapid widening can signal fragmentation, tighter financing and a stronger bank-sovereign feedback loop.'}}
function euroFragmentationIndicators(f){let rows=[fragmentationSpreadIndicator(f,'IRLTLT01FRM156N','France − Germany 10Y spread'),fragmentationSpreadIndicator(f,'IRLTLT01ITM156N','Italy − Germany 10Y spread'),fragmentationSpreadIndicator(f,'IRLTLT01ESM156N','Spain − Germany 10Y spread')],comp=avg(rows.map(x=>x.score));rows.push({name:'Euro Sovereign Fragmentation Composite',value:comp,unit:'/100',score:comp,source:'Composite: France/Italy/Spain 10Y spreads vs Germany',date:rows.map(x=>x.date).filter(Boolean).sort().at(-1)||null,trend:'Sovereign fragmentation',meaningHr:'Kompozit prati širi li se stres državnog financiranja unutar Europe u odnosu na Bund. Visok score može povećati pritisak na europske banke, kreditne uvjete i ECB transmisiju. Za Hrvatsku je posebno relevantan jer je u eurozoni; za Njemačku je važan kroz banke, trgovinu i ulogu Bunda kao referentnog safe-haven tržišta.',meaningEn:'The composite tracks whether sovereign-financing stress is widening across Europe relative to Bunds. A high score can pressure European banks, credit conditions and ECB transmission. It is especially relevant for Croatia as a euro-area member and for Germany through banks, trade and the Bund’s benchmark safe-haven role.'});return rows}
function sovereignBondStressIndicators(f,market){let out=[];
 for(const spec of [
  ['THREEFYTP10','10Y Treasury term-premium shock','Naglo povećanje 10Y term premije znači da investitori traže veću kompenzaciju za duration/rate rizik, ne samo da očekuju više policy stope. To može pritisnuti valuacije i povećati trošak financiranja.','A sharp rise in the 10-year term premium means investors demand more compensation for duration/rate risk, not merely higher expected policy rates. This can pressure valuations and raise financing costs.'],
  ['THREEFFTP10','Long-horizon forward term-premium shock','Rast dugoročnog forward term premiuma sugerira da tržište repricira trajni duration/fiscal/inflation rizik na udaljenom horizontu. To je važnije ako istodobno raste MOVE i slabi stock-bond hedge.','A rise in long-horizon forward term premium suggests repricing of persistent duration/fiscal/inflation risk far into the future. It matters more when MOVE rises and the stock-bond hedge weakens.']]){
   let [id,name,hr,en]=spec,s=f[id]||[],r=changeShockRisk(s,20,756),last=latestPoint(s),levelP=last?percentileRank(s.slice(-2520).map(x=>x.v),last.v):null,score=avg([r.score,percentileRisk(levelP)]);out.push({name,value:last&&last.v,unit:'%',score,source:'FRED '+id,sourceUrl:FRED+id,provider:'FRED',dataKind:'market',date:last&&last.d,trend:'Sovereign bond stress',percentile:levelP,change20:Number.isFinite(r.change)?r.change*100:null,meaningHr:hr,meaningEn:en});
 }
 let tlt=market&&market.tlt?marketMetrics(market.tlt):null,tltScore=tlt?avg([trendRisk(tlt),volRisk(tlt.rv20)]):null;out.push({name:'Long-Treasury market stress · TLT',value:tlt&&tlt.rv20,unit:'% vol',score:tltScore,source:'Yahoo Finance TLT',date:tlt&&tlt.date,trend:'Sovereign bond stress',meaningHr:'TLT kombinira tržišni direction i realized volatility dugog Treasury durationa. Slabost uz rast volatilnosti i term premije pojačava signal da je core sovereign bond tržište izvor stresa, a ne zaštita.','meaningEn':'TLT combines market direction and realized volatility in long Treasury duration. Weakness alongside rising volatility and term premium strengthens the signal that core sovereign bonds are a source of stress rather than a hedge.'});
 let move=(f.MOVE||[]),moveLast=latestPoint(move),moveScore=moveLast?(moveLast.v<100?25:moveLast.v<120?55:82):null,comp=avg([...out.map(x=>x.score),moveScore]);out.push({name:'Core Sovereign Bond Stress Composite',value:comp,unit:'/100',score:comp,source:'Composite: term premia + TLT + MOVE',date:out.map(x=>x.date).filter(Boolean).sort().at(-1)||null,trend:'Sovereign bond stress',meaningHr:'Kompozit kombinira term premium, Treasury market stres i MOVE. Visok rezultat upozorava da core sovereign bonds mogu pojačavati, umjesto amortizirati, šokove u drugim klasama imovine.','meaningEn':'Composite combines term premium, Treasury market stress and MOVE. A high reading warns that core sovereign bonds may amplify rather than absorb shocks in other asset classes.'});return out}
function standardizedIndexIndicator(f,id,name,meaningHr,meaningEn){let s=f[id]||[];if(!s.length)return{name,value:null,unit:'',score:null,source:'FRED '+id,date:null,trend:'NBFI / leverage',meaningHr,meaningEn,note:'Data unavailable; excluded from score.'};let x=s[s.length-1],p=percentileRank(s.slice(-1040).map(q=>q.v),x.v);return{name,value:x.v,unit:'',score:percentileRisk(p),source:'FRED '+id,sourceUrl:FRED+encodeURIComponent(id),provider:'FRED',dataKind:'weekly',date:x.d,trend:'NBFI / leverage',percentile:p,meaningHr,meaningEn}}
function nbfiIndicators(f,market){let out=[];
 out.push(standardizedIndexIndicator(f,'NFCIRISK','NFCI risk subindex','Chicago Fed risk subindex obuhvaća volatilnost i funding risk u tradicionalnom i shadow-bank sustavu. Rast prema gornjem povijesnom percentilu znači da tržišni/funding rizik postaje šire prisutan.','The Chicago Fed risk subindex captures volatility and funding risk across traditional and shadow banking. A move toward the upper historical percentile means market/funding risk is becoming more broadly present.'));
 out.push(standardizedIndexIndicator(f,'NFCICREDIT','NFCI credit subindex','Credit subindex mjeri uvjete dostupnosti i cijene kredita. Rast znači pooštravanje uvjeta i može prethoditi slabijem investiranju, potrošnji i corporate refinancingu.','The credit subindex measures credit availability and pricing conditions. A rise means tighter conditions and can precede weaker investment, consumption and corporate refinancing.'));
 out.push(standardizedIndexIndicator(f,'NFCILEVERAGE','NFCI financial leverage subindex','Ovaj podindeks prati promjene financijske poluge. Ekstremna promjena prema tighter režimu može signalizirati deleveraging i prisilno smanjenje rizika, što pojačava tržišne šokove.','This subindex tracks changes in financial leverage. An extreme move toward tighter conditions can signal deleveraging and forced risk reduction, amplifying market shocks.'));
 out.push(standardizedIndexIndicator(f,'NFCINONFINLEVERAGE','NFCI nonfinancial leverage subindex','Nonfinancial leverage je dio financial-accelerator kanala: slabiji asset values i tighter credit mogu prisiliti kućanstva i kompanije na deleveraging, čime se financijski stres prenosi u realnu ekonomiju.','Nonfinancial leverage is part of the financial-accelerator channel: weaker asset values and tighter credit can force households and firms to deleverage, transmitting financial stress into the real economy.'));
 let bizd=market&&market.bizd?marketMetrics(market.bizd):null,bkln=market&&market.bkln?marketMetrics(market.bkln):null;let bizdScore=bizd?avg([trendRisk(bizd),volRisk(bizd.rv20)]):null,bklnScore=bkln?avg([trendRisk(bkln),volRisk(bkln.rv20)]):null;
 out.push({name:'Private-credit market proxy · BIZD',value:bizd&&bizd.m1,unit:'% 1M',score:bizdScore,source:'Yahoo Finance BIZD',date:bizd&&bizd.date,trend:'NBFI / leverage',meaningHr:'BIZD je tržišni proxy za listed business-development companies, a ne direktna valuacija cijelog private-credit tržišta. Slabost uz rast HY spreadova i bankarskog stresa povećava signalnu vrijednost.','meaningEn':'BIZD is a market proxy for listed business-development companies, not a direct valuation of the entire private-credit market. Weakness is more informative when HY spreads and banking stress rise as well.'});
 out.push({name:'Leveraged-loan proxy · BKLN',value:bkln&&bkln.m1,unit:'% 1M',score:bklnScore,source:'Yahoo Finance BKLN',date:bkln&&bkln.date,trend:'NBFI / leverage',meaningHr:'BKLN daje brži tržišni proxy za leveraged-loan segment. Pad cijene uz rast volatilnosti može signalizirati slabiju likvidnost i povećanu zabrinutost oko visoko zaduženih dužnika.','meaningEn':'BKLN provides a faster market proxy for leveraged loans. Falling prices with rising volatility can signal weaker liquidity and greater concern about highly leveraged borrowers.'});
 let comp=avg(out.map(x=>x.score));out.push({name:'NBFI & Leveraged-Finance Stress Composite',value:comp,unit:'/100',score:comp,source:'Composite: NFCI subindexes + BIZD + BKLN',date:out.map(x=>x.date).filter(Boolean).sort().at(-1)||null,trend:'NBFI / leverage',meaningHr:'Kompozit kombinira shadow-bank/funding uvjete s tržišnim proxyjima private credita i leveraged loansa. Visok rezultat je warning za deleveraging i liquidity amplification, ne dokaz insolventnosti sektora.','meaningEn':'Composite combines shadow-bank/funding conditions with market proxies for private credit and leveraged loans. A high reading warns about deleveraging and liquidity amplification, not proof of sector insolvency.'});return out}
