 let mr=changeShockRisk(f.MORTGAGE30US||[],13,520);out.push({name:'Mortgage-rate shock · 13w',value:Number.isFinite(mr.change)?mr.change*100:null,unit:' bp/13w',score:mr.score,source:'FRED MORTGAGE30US',sourceUrl:FRED+'MORTGAGE30US',provider:'FRED',dataKind:'weekly',date:mr.date,trend:'Credit / real estate',percentile:mr.percentile,direction:mr.direction,meaningHr:'Brz rast hipotekarnih stopa pogoršava affordability, usporava transakcije i povećava refinancing pritisak. Važniji je ako istodobno slabe homebuilder/REIT dionice i rastu delinquencies.','meaningEn':'A rapid rise in mortgage rates worsens affordability, slows transactions and increases refinancing pressure. It matters more when homebuilder/REIT equities weaken and delinquencies rise at the same time.'});
 let iyr=market&&market.iyr?marketMetrics(market.iyr):null,xhb=market&&market.xhb?marketMetrics(market.xhb):null;let iyrScore=iyr?avg([trendRisk(iyr),volRisk(iyr.rv20)]):null,xhbScore=xhb?avg([trendRisk(xhb),volRisk(xhb.rv20)]):null;
 out.push({name:'US REIT market stress · IYR',value:iyr&&iyr.m3,unit:'% 3M',score:iyrScore,source:'Yahoo Finance IYR',date:iyr&&iyr.date,trend:'Credit / real estate',meaningHr:'Slabljenje širokog REIT tržišta može anticipirati pritisak na valuations i refinancing prije nego što se pojavi u tromim kvartalnim bankarskim statistikama.','meaningEn':'Weakness in the broad REIT market can anticipate valuation and refinancing pressure before it appears in slow quarterly bank statistics.'});
