function eventHistory(h){let out=[];for(let i=1;i<h.length;i++){let a=riskBand(h[i-1].global).label,b=riskBand(h[i].global).label;if(a!==b)out.push({day:h[i].day,text:'Global regime '+a+' → '+b,score:h[i].global});for(const c of activeMarketConfig()){let pa=h[i-1].countries&&h[i-1].countries[c.code],pb=h[i].countries&&h[i].countries[c.code];if(Number.isFinite(pa)&&Number.isFinite(pb)){let x=riskBand(pa).label,y=riskBand(pb).label;if(x!==y)out.push({day:h[i].day,text:c.name+' '+x+' → '+y,score:pb})}}}return out.slice(-30).reverse()}
