function genericCorrContext(a,b){let A=MARKET_CONFIG.find(x=>x.code===a)||{},B=MARKET_CONFIG.find(x=>x.code===b)||{},bits=[];if(A.euro&&B.euro)bits.push('shared ECB policy, EUR financial conditions and the euro-area business cycle');if(A.region&&A.region===B.region)bits.push('regional growth, investor flows and common risk sentiment');for(const code of [a,b])if(DRIVER_KEYS[code])bits.push(DRIVER_KEYS[code]);if(!bits.length)bits.push('global growth, rates and cross-border risk appetite');return [...new Set(bits)].slice(0,3).join('; ')}
function corrStrength(v){let a=Math.abs(v);return a<.2?t('low'):a<.5?t('normal'):a<.75?t('high'):t('extreme')}
