function renderCorr(){let c=appState.corr;if(!c)return;if(!appState.corrDiagnostic&&Object.keys(appState.series||{}).length){try{appState.corrDiagnostic=correlationRegimeDiagnostic(Object.fromEntries(appState.countries.filter(x=>appState.series[x.code]).map(x=>[x.code,appState.series[x.code]])))}catch(_){}}let rc=$('corrRegimeCard');if(rc)rc.innerHTML=correlationRegimeCardHtml(appState.corrDiagnostic);if($('corrHistoryTitle'))$('corrHistoryTitle').textContent=L('Povijest korelacijskog stresa','Correlation Stress History');if($('corrHistorySub'))$('corrHistorySub').textContent=L('20D / 60D / 120D prosječna korelacija parova · lokalni dnevni snapshoti','20D / 60D / 120D average pairwise correlation · local daily snapshots');let h='<table class="corr"><tr><th></th>'+c.labels.map(x=>'<th>'+x+'</th>').join('')+'</tr>';c.mat.forEach((r,i)=>{h+='<tr><th>'+c.labels[i]+'</th>'+r.map((v,j)=>corrCell(v,c.labels[i],c.labels[j],i===j)).join('')+'</tr>'});h+='</table>';$('corrTable').innerHTML=h;$('corrNote').innerHTML=`${esc(t('window'))}: <b>${c.window===756?'3Y':c.window+'D'}</b> · ${esc(t('avg_corr'))}: <b>${Number.isFinite(c.average)?c.average.toFixed(2):'N/A'}</b> · ${esc(t('regime'))}: <span class="pill ${correlationRegimeClass(c.regime)}">${esc(c.regime)}</span>. ${esc(t('returns_note'))}`;let pairs=[];for(let i=0;i<c.labels.length;i++)for(let j=i+1;j<c.labels.length;j++)pairs.push({a:c.labels[i],b:c.labels[j],v:c.mat[i][j]});pairs.sort((x,y)=>(Number.isFinite(y.v)?Math.abs(y.v):-1)-(Number.isFinite(x.v)?Math.abs(x.v):-1));$('corrExplanations').innerHTML=pairs.map(p=>`<details class="corr-expl"><summary><span>${esc(p.a)} ↔ ${esc(p.b)}</span><b>${Number.isFinite(p.v)?p.v.toFixed(2):'N/A'}</b></summary><div>${esc(corrExplanation(p.a,p.b,p.v))}</div></details>`).join('');document.querySelectorAll('.corr-cell').forEach(td=>td.onclick=()=>selectCorrPair(td.dataset.a,td.dataset.b));let first=pairs.find(x=>Number.isFinite(x.v))||pairs[0];if(first)selectCorrPair(first.a,first.b);{let channels=['US → Europe → Germany: credit/rates and global risk appetite','China → Germany: export and industrial-demand sensitivity','China/Hong Kong → Asia: growth, property and liquidity channel','Japan rates → Global bonds → Equities: duration and carry channel','US/China → Philippines: USD liquidity, Asian growth and foreign portfolio flows','China → South Korea/Taiwan/Australia: semiconductor, export and commodity demand','Oil → Saudi Arabia/UAE → Global EM: energy revenue and liquidity channel','Brazil/Chile/South Africa → Global commodities: metals and China-demand channel','Euro area → Poland/Nordics: trade, rates and regional growth','CHF → Europe: safe-haven and financial-conditions channel'];if(currentLang==='hr')channels.splice(4,0,'Euro area → Croatia: ECB conditions, EU trade and regional capital flows');$('channels').innerHTML=channels.map(x=>'<div class="event">'+esc(x)+'</div>').join('')}requestAnimationFrame(drawCorrelationHistory)}
function renderHistory(){drawHistory();let ev=eventHistory(appState.history);$('historyEvents').innerHTML=ev.length?ev.map(e=>`<div class="event" style="border-left-color:${barColor(e.score)}"><b>${esc(e.day)}</b> · ${esc(e.text)} · score ${Math.round(e.score)}</div>`).join(''):'<div class="small">'+esc(t('status_empty'))+'</div>'}
function drawHistory(){let cv=$('historyCanvas'),r=cv.getBoundingClientRect(),dpr=window.devicePixelRatio||1,w=Math.max(300,r.width),h=210;cv.width=w*dpr;cv.height=h*dpr;let x=cv.getContext('2d');x.scale(dpr,dpr);x.clearRect(0,0,w,h);let grid=themeCss('--chart-grid','#d8dee6'),axis=themeCss('--chart-axis','#667085'),accent=themeCss('--accent','#245b8a');x.strokeStyle=grid;x.lineWidth=1;[25,45,60,75].forEach(v=>{let y=h-18-v/100*(h-30);x.beginPath();x.moveTo(30,y);x.lineTo(w-8,y);x.stroke()});let rows=appState.history||[];setChartPeriodV45(cv,[{data:rows.filter(q=>q&&q.day&&Number.isFinite(q.global)).map(q=>({d:q.day,v:q.global}))}],{frequency:L('Dnevni snapshot','Daily snapshot')});if(rows.length<2){x.fillStyle=axis;x.font='11px sans-serif';x.fillText('History begins after daily refreshes.',38,104);return}x.strokeStyle=accent;x.lineWidth=2.4;x.beginPath();rows.forEach((q,i)=>{let px=30+i/(rows.length-1)*(w-42),py=h-18-q.global/100*(h-30);i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke();x.fillStyle=axis;x.font='9px sans-serif';let fd=chartDateV45(rows[0].day),ld=chartDateV45(rows[rows.length-1].day),span=fd&&ld?(ld-fd)/86400000:null,a=chartAxisDateV45(rows[0].day,span),b=chartAxisDateV45(rows[rows.length-1].day,span);x.fillText(a,30,h-3);let bw=x.measureText(b).width;x.fillText(b,Math.max(30,w-8-bw),h-3)}
