function openMarket(code,pushRoute=true){let c=appState.countries.find(x=>x.code===code);if(!c)return;$('modalTitle').textContent=c.flag+' '+marketName(c)+' · '+c.index;let m=c.metrics,mac=c.macroData||{},de=code==='DE'?appState.special.find(x=>x.name.startsWith('German')):null,eq=appState.equity&&appState.equity.byCode&&appState.equity.byCode[code],limitedMarket=!!c.limited||!m;let metricRows=m?`<tr><td>${esc(t('market'))}</td><td>${fmt(m.value,m.value>1000?0:1)}</td><td>${fmtPct(m.d1)}</td><td>${fmtPct(m.m3)}</td></tr><tr><td>${esc(t('distance_200'))}</td><td>${fmtPct(m.dist200)}</td><td>${esc(t('drawdown_52'))}</td><td>${fmtPct(m.draw52)}</td></tr><tr><td>${esc(t('realized_vol'))}</td><td>${fmtPct(m.rv20)}</td><td>${esc(t('ma_cross'))}</td><td>${fmtPct(m.maCross)}</td></tr>`:`<tr><td colspan="4">${esc(t('series_unavailable'))}</td></tr>`;let eqHtml=eq?`<div class="section-title">${esc(L('Equity Market Internals','Equity Market Internals'))}</div><div class="visual-card"><div class="visual-head"><div><div class="visual-title">${esc(eq.regime)}</div><div class="visual-sub">${esc(equityMeaning(eq))}</div></div><div>${statusPill(eq.score)} <b>${Number.isFinite(eq.score)?Math.round(eq.score)+'/100':'N/A'}</b></div></div>${Number.isFinite(eq.divergence)&&eq.divergence>=15?`<div class="divergence-banner"><b>${esc(L('Headline vs internals divergencija','Headline vs internals divergence'))}</b><br>${esc(L('Internals rizik je','Internals risk is'))} ${fmt(eq.divergence,0)} ${esc(L('bodova iznad headline price-risk signala.','points above the headline price-risk signal.'))}</div>`:''}<div class="internals-grid" style="margin-top:9px"><div class="internal-card"><div class="ih"><span>Breadth</span><span>${Number.isFinite(eq.breadth&&eq.breadth.score)?Math.round(eq.breadth.score):'N/A'}</span></div><div class="iv">${Number.isFinite(eq.breadth&&eq.breadth.above50)?fmt(eq.breadth.above50,0)+'%':'N/A'}</div><div class="inote">${esc(L('proxy iznad 50DMA','proxy above 50DMA'))}</div></div><div class="internal-card"><div class="ih"><span>${esc(L('Pokrivenost','Coverage'))}</span><span>${eq.coverage}%</span></div><div class="iv">${esc(eq.confidence)}</div><div class="inote">${esc(L('normalizirano preko dostupnih signala','normalized across available signals'))}</div></div></div><div style="margin-top:10px">${riskBarHtml(eq.parts)}</div></div>`:'';let charts=`<div class="section-title">${esc(L('Grafikoni tržišta','Market charts'))}</div><div class="visual-card"><div class="chart-controls" id="marketChartControls"><button class="chart-btn" data-range="22">1M</button><button class="chart-btn" data-range="66">3M</button><button class="chart-btn active" data-range="252">1Y</button><button class="chart-btn" data-range="756">3Y</button></div><div class="visual-title">${esc(c.index)} · ${esc(L('povijest cijene','price history'))}</div><div class="chart-wrap"><canvas id="marketPriceChart" class="chart-canvas"></canvas></div></div>${eq?`<div class="visual-card" style="margin-top:9px"><div class="visual-title">${esc(L('Relativna participacija · normalizirano na 100','Relative participation · normalized to 100'))}</div><div class="visual-sub">${esc(L('Uspoređuje headline indeks s equal-weight, small/mid-cap ili sekundarnim indeksima kada su podaci dostupni.','Compares the headline index with equal-weight, small/mid-cap or secondary indexes when data are available.'))}</div><div class="chart-wrap"><canvas id="marketRelativeChart" class="chart-canvas"></canvas></div><div id="marketRelativeLegend" class="chart-legend"></div></div>`:''}${code==='US'&&eq&&eq.aux&&eq.aux.options?`<div class="visual-card" style="margin-top:9px"><div class="visual-title">US options stress · normalized</div><div class="visual-sub">VIX, VIX3M and VVIX show whether hedging stress is broadening or concentrating in the near term.</div><div class="chart-wrap"><canvas id="marketOptionsChart" class="chart-canvas"></canvas></div><div id="marketOptionsLegend" class="chart-legend"></div></div>`:''}`;let special='';if(de)special=`<div class="section-title">German Industrial Stress</div><div class="panel"><b>${de.score}/100</b> · ${statusPill(de.score)}<div class="contributors" style="margin-top:8px">${(de.extra.details||[]).map(x=>`<div class="contrib"><span>${esc(x.name)}</span><b>${Math.round(x.score)}</b></div>`).join('')}</div></div>`;if(hasIndustryMarket(code)){let industryTitle=code==='DE'?L('Njemačka · pregled po industrijama','Germany · industry overview'):code==='HR'?L('Hrvatska · službeni sektorski indeksi','Croatia · official sector indices'):(marketName(c)+' · '+L('pregled po industrijama','industry overview'));special+=`<div class="section-title">${esc(industryTitle)}</div><div id="industryPanel-${code}">${industrySectionInner(code)}</div>`;}let tradeCtx=(appState.early||[]).find(x=>x.name==='Global Trade & Shipping Stress Composite');if((code==='DE'||code==='HR')&&tradeCtx)special+=`<div class="section-title">${esc(code==='DE'?L('Njemačka · izvoz i trgovinski ciklus','Germany · export & trade cycle'):L('Hrvatska · vanjska potražnja i trgovinski kanal','Croatia · external-demand & trade channel'))}</div><div class="panel"><b>${Number.isFinite(tradeCtx.score)?Math.round(tradeCtx.score)+'/100':'N/A'}</b> · ${statusPill(tradeCtx.score)}<div class="meaning-box">${esc(code==='DE'?L('Slabije izvozne narudžbe, realizirani izvoz i freight aktivnost mogu prethoditi slabijim prihodima cikličkih njemačkih industrija.','Weaker export orders, realized exports and freight activity can precede weaker revenues for cyclical German industries.'):L('Slabiji europski trgovinski ciklus može se prenijeti na Hrvatsku kroz turizam, transport, industriju i investicijsku potražnju.','A weaker European trade cycle can reach Croatia through tourism, transport, industry and investment demand.'))}</div></div>`;let fragCtx=(appState.early||[]).find(x=>x.name==='Euro Sovereign Fragmentation Composite');if((code==='DE'||code==='HR')&&fragCtx)special+=`<div class="section-title">${esc(L('Eurozona · sovereign fragmentacija','Euro-area sovereign fragmentation'))}</div><div class="panel"><b>${Number.isFinite(fragCtx.score)?Math.round(fragCtx.score)+'/100':'N/A'}</b> · ${statusPill(fragCtx.score)}<div class="meaning-box">${esc(code==='HR'?L('Širenje spreadova prema Bundu može pogoršati europske financijske uvjete i preko banaka/ECB transmisije utjecati i na hrvatsko financiranje.','Wider spreads versus Bunds can tighten European financial conditions and reach Croatian financing through banks and ECB transmission.'):L('Bund je benchmark europskog sovereign tržišta; širenje francuskih, talijanskih i španjolskih spreadova povećava rizik europske fragmentacije i bank-sovereign povratne sprege.','Bunds are the benchmark for euro sovereign risk; wider French, Italian and Spanish spreads increase fragmentation and bank-sovereign feedback risk.'))}</div></div>`;$('modalBody').innerHTML=`<div class="hero" style="grid-template-columns:1fr"><div><h2 style="margin:0">${limitedMarket?esc(L('Tržišni signal: ograničeni podaci','Market signal: limited data')):esc(t('country_risk'))+' '+(Number.isFinite(c.risk)?Math.round(c.risk):'N/A')}</h2>${limitedMarket?'<span class="pill status-limited">LIMITED DATA</span>':statusPill(c.risk)}<div class="meta">${limitedMarket?esc(L('Makro/FX kontekst može ostati dostupan, ali bez valjane headline tržišne serije ne dodjeljuje se GREEN/ORANGE/RED tržišni status.','Macro/FX context may remain available, but without a valid headline market series no GREEN/ORANGE/RED market status is assigned.')):esc(t('composite_note'))}</div><div class="meaning-box"><b>${esc(L('Što to znači za tržište','What it means for the market'))}:</b> ${esc(countryMeaning(c))}</div></div></div>${charts}${eqHtml}${c.coverageV50?`<div class="section-title">${esc(L('Pokrivenost modela','Model coverage'))}</div><div class="quality"><div class="qitem"><b>${esc(L('Pokrivenost podataka','Data coverage'))}</b><span>${c.coverageV50.dataCoverage}%</span></div><div class="qitem"><b>${esc(L('Faktorska pokrivenost','Factor coverage'))}</b><span>${c.coverageV50.factorCoverage}% · ${c.coverageV50.factorGroups}/${Object.keys(COUNTRY_FACTOR_GROUPS_V50).length}</span></div><div class="qitem"><b>${esc(L('Pokrivenost svježine','Freshness coverage'))}</b><span>${c.coverageV50.freshnessCoverage}%</span></div><div class="qitem"><b>${esc(L('Efektivna ponderirana','Effective weighted'))}</b><span>${c.coverageV50.effectiveWeightedCoverage}%</span></div></div>${c.limited?`<div class="meaning-box"><b>LIMITED DATA</b> · ${esc(c.coverageV50.reason)}</div>`:''}`:''}<div class="section-title">${esc(t('risk_subscores'))}</div><div class="score-grid">${scoreBox('market',c.subscores.market)}${scoreBox('macro',c.subscores.macro)}${scoreBox('credit',c.subscores.credit)}${scoreBox('liquidity',c.subscores.liquidity)}${scoreBox('valuation',c.subscores.valuation)}${scoreBox('technical',c.subscores.technical)}${scoreBox('systemic',c.subscores.systemic)}</div><div class="section-title">${esc(t('market_metrics'))}</div><div class="panel"><table class="data-table"><tbody>${metricRows}</tbody></table></div><div class="section-title">${esc(t('macro_context'))}</div><div class="quality"><div class="qitem"><b>${esc(t('gdp_growth'))}</b><span>${mac.gdp?fmt(mac.gdp.value,1)+'% · '+mac.gdp.year:'N/A'}</span></div><div class="qitem"><b>${esc(t('inflation'))}</b><span>${mac.inf?fmt(mac.inf.value,1)+'% · '+mac.inf.year:'N/A'}</span></div><div class="qitem"><b>${esc(t('unemployment'))}</b><span>${mac.un?fmt(mac.un.value,1)+'% · '+mac.un.year:'N/A'}</span></div><div class="qitem"><b>${esc(t('currency'))}</b><span>${c.fxMetrics?esc(c.currency)+' RV20 '+fmt(c.fxMetrics.rv20,1)+'%':'N/A'}</span></div></div><div class="section-title">${esc(t('main_contributors'))}</div><div class="contributors">${c.contributors.slice(0,6).map(x=>`<div class="contrib"><span>${esc(x.name)}</span><b>${Math.round(x.score)}</b></div>`).join('')}</div><div class="section-title">${esc(L('Najvažnije kompanije i dionice','Key companies & stocks'))}</div><div id="countryCompanies-${code}">${countryCompaniesHtml(code)}</div>${fiscalCountryDetailHtmlV43(code)}${special}<div class="section-title">${esc(t('data_quality'))}</div><div class="panel small">${esc(t('market_source'))}: ${c.quality.sourceUrl?`<a class="source-link" href="${esc(c.quality.sourceUrl)}" target="_blank" rel="noopener">${esc(c.quality.source)}</a>`:esc(c.quality.source)} · ${esc(t('latest'))} ${esc(c.quality.date||'N/A')} · ${esc(L('Svježina','Freshness'))} ${esc(c.quality.freshness||'N/A')} · ${esc(t('confidence'))} ${esc(c.quality.confidence)}${c.quality.retrievedAt?' · '+esc(L('Dohvaćeno','Retrieved'))+' '+esc(new Date(c.quality.retrievedAt).toLocaleString(locale())):''}. ${esc(t('wb_note'))}</div>`;$('detailModal').classList.add('show');ensureCountryCompanies(code).catch(()=>{});if(hasIndustryMarket(code))refreshIndustryPanel(code);requestAnimationFrame(()=>{drawMarketCharts(code,252);document.querySelectorAll('#marketChartControls .chart-btn').forEach(b=>b.onclick=()=>{document.querySelectorAll('#marketChartControls .chart-btn').forEach(x=>x.classList.toggle('active',x===b));drawMarketCharts(code,Number(b.dataset.range))})});let target='#market='+encodeURIComponent(code);if(pushRoute&&location.hash!==target)pushDetailRoute('market',{code},target)}
function activePageId(){let p=document.querySelector('.page.active');return p?p.id:'overview'}
function parseDetailRoute(){let h=String(location.hash||'').replace(/^#/,'');if(!h)return null;let p=new URLSearchParams(h);if(p.has('market'))return{kind:'market',code:p.get('market')};if(p.has('watch'))return{kind:'watch',code:p.get('watch')};if(p.has('stock'))return{kind:'stock',symbol:p.get('stock'),country:p.get('country')||'',industry:p.get('industry')||''};if(p.has('etf'))return{kind:'etf',symbol:p.get('etf')};return null}
function detailHash(kind,data={}){let p=new URLSearchParams();if(kind==='market')p.set('market',data.code||'');if(kind==='watch')p.set('watch',data.code||'');if(kind==='stock'){p.set('stock',data.symbol||'');if(data.country)p.set('country',data.country);if(data.industry)p.set('industry',data.industry)}if(kind==='etf')p.set('etf',data.symbol||'');return'#'+p.toString()}
function rememberOriginState(){let r=parseDetailRoute();if(r)return;let st=Object.assign({},history.state||{},{mrmBase:true,page:activePageId(),scrollY:Math.round(window.scrollY||0)});history.replaceState(st,'',location.href)}
function pushDetailRoute(kind,data={},targetHash=''){let target=targetHash||detailHash(kind,data);if(location.hash===target)return;rememberOriginState();history.pushState({mrmDetail:true,kind,...data,page:activePageId(),parentMarket:(parseDetailRoute()||{}).kind==='market'},'',target)}
function closeMarketDetail(){let r=parseDetailRoute();if(r&&(r.kind==='market'||r.kind==='watch')){history.back();return}$('detailModal').classList.remove('show')}
function restoreBaseState(st){if(!st||!st.mrmBase)return;let page=st.page||activePageId();if(page!==activePageId())navTo(page,false);let y=Number(st.scrollY);if(Number.isFinite(y))setTimeout(()=>window.scrollTo(0,y),0)}
function syncAppRoute(ev){let r=parseDetailRoute(),st=(ev&&ev.state)||history.state||null;if(location.hash==='#help'){hideStockDetail();$('detailModal').classList.remove('show');openHelp(false);return}if($('helpModal'))$('helpModal').classList.remove('show');if(r&&r.kind==='market'){hideStockDetail();let c=appState.countries.find(x=>x.code===r.code);if(c)openMarket(r.code,false);else $('detailModal').classList.remove('show');return}if(r&&r.kind==='watch'){hideStockDetail();openExtendedCountry(r.code,false).catch(()=>{});return}if(r&&r.kind==='stock'){if(!(st&&st.parentMarket))$('detailModal').classList.remove('show');openStockDetail(r.symbol,{country:r.country||'',industry:r.industry||''},false).catch(()=>{});return}if(r&&r.kind==='etf'){$('detailModal').classList.remove('show');openEtfDetail(r.symbol,false).catch(()=>{});return}hideStockDetail();$('detailModal').classList.remove('show');restoreBaseState(st)}
function handleAppBack(){if($('helpModal')&&$('helpModal').classList.contains('show')){closeHelp();return true}if($('stockModal').classList.contains('show')){closeStockDetail();return true}if($('detailModal').classList.contains('show')){closeMarketDetail();return true}let p=activePageId();if(p&&p!=='overview'){navTo('overview');return true}return false}
window.MRMHandleBack=handleAppBack;

// v3.5.1_18 — integrated bilingual Help (English/Croatian). Pure UI/documentation: no data-plane changes.
let helpLangOverride=null;
function helpLanguage(){return helpLangOverride||((currentLang==='hr')?'hr':'en')}
function HH(hr,en){return helpLanguage()==='hr'?hr:en}
function helpSection(id,titleHr,titleEn,bodyHr,bodyEn,open=false){return `<details class="help-topic" data-help-id="${esc(id)}" ${open?'open':''}><summary>${esc(HH(titleHr,titleEn))}</summary><div class="help-content">${HH(bodyHr,bodyEn)}</div></details>`}
function helpRiskBands(){return `<div class="help-bands"><div class="help-band green"><b>0–24</b>GREEN<br>RISK ON</div><div class="help-band lightgreen"><b>25–44</b>LIGHT GREEN<br>NORMAL</div><div class="help-band orange"><b>45–59</b>ORANGE<br>CAUTION</div><div class="help-band darkorange"><b>60–74</b>DARK ORANGE<br>RISK OFF</div><div class="help-band red"><b>75–100</b>RED<br>SYSTEMIC STRESS</div></div>`}
function helpHtml(){
 const HR=helpLanguage()==='hr';
 let sections=[];
 sections.push(helpSection('quick','Brzi početak — kako koristiti aplikaciju','Quick start — how to use the app',
 `<p><b>Market Risk Monitor nije predictor cijene.</b> Njegova glavna svrha je procijeniti <b>režim tržišnog rizika</b> i pokazati potvrđuju li isti problem različite skupine podataka.</p><ol><li>Prvo pogledaj <b>GLOBAL risk</b>, Coverage i Confidence.</li><li>Zatim pogledaj <b>zašto</b> se score promijenio — Credit/Funding, Volatility, Equity, Macro, Liquidity, Rates, FX, Commodities i Correlation.</li><li>Provjeri je li slabost potvrđena u <b>EARLY</b>, <b>MACRO</b> i <b>S&amp;P Hidden Weakness</b>.</li><li>Za konkretnu zemlju, dionicu ili ETF otvori detalj tek kada ti treba.</li><li>Ne reagiraj na jedan indikator. Najvrjedniji signal je <b>potvrda više neovisnih kategorija</b>.</li></ol><div class="help-callout warn"><b>Važno:</b> 70/100 znači visok modelirani stres, ne 70% vjerojatnosti pada tržišta.</div>`,
 `<p><b>Market Risk Monitor is not a price predictor.</b> Its main purpose is to estimate the <b>market-risk regime</b> and show whether different data families confirm the same problem.</p><ol><li>Start with <b>GLOBAL risk</b>, Coverage and Confidence.</li><li>Then inspect <b>why</b> the score moved — Credit/Funding, Volatility, Equity, Macro, Liquidity, Rates, FX, Commodities and Correlation.</li><li>Check whether weakness is confirmed in <b>EARLY</b>, <b>MACRO</b> and <b>S&amp;P Hidden Weakness</b>.</li><li>Open country, stock or ETF detail only when needed.</li><li>Do not react to one indicator. The strongest information is <b>confirmation across independent families</b>.</li></ol><div class="help-callout warn"><b>Important:</b> 70/100 means high modeled stress, not a 70% probability that the market will fall.</div>`,true));
 sections.push(helpSection('score','Risk score, boje, Coverage i Confidence','Risk score, colors, Coverage and Confidence',
 `<p>Za većinu risk scoreova vrijedi: <b>viši broj = veći stres/rizik</b>.</p>${helpRiskBands()}<h5>Coverage</h5><p>Coverage pokazuje koliki dio planiranih signala stvarno ima valjan podatak. Nedostajući podatak se <b>ne pretvara u nulu</b>; težine se normaliziraju samo preko dostupnih signala.</p><h5>Confidence</h5><p>Confidence opisuje koliko je rezultat potkrijepljen dostupnim izvorima i pokrivenošću. Za GLOBAL model HIGH tipično zahtijeva najmanje oko 85% pokrivenosti i dobru dostupnost providera; MEDIUM oko 60%+; niže od toga tretiraj kao LOW.</p><div class="help-callout"><b>Primjer:</b> Risk 68 / Coverage 92% / HIGH je snažniji zaključak od Risk 68 / Coverage 45% / LOW.</div><p><b>N/A</b> znači da nema dovoljno valjanih podataka. <b>STALE/DELAYED/CACHED</b> znači da postoji zadnji valjani podatak, ali nije potpuno svjež.</p>`,
 `<p>For most risk scores: <b>a higher number means more stress/risk</b>.</p>${helpRiskBands()}<h5>Coverage</h5><p>Coverage shows how much of the intended signal set has valid data. Missing data are <b>not converted to zero</b>; weights are renormalized only across available signals.</p><h5>Confidence</h5><p>Confidence describes how well the result is supported by available sources and coverage. For the GLOBAL model, HIGH typically requires roughly 85%+ coverage and good provider availability; MEDIUM roughly 60%+; below that should be treated as LOW.</p><div class="help-callout"><b>Example:</b> Risk 68 / Coverage 92% / HIGH is a stronger conclusion than Risk 68 / Coverage 45% / LOW.</div><p><b>N/A</b> means insufficient valid data. <b>STALE/DELAYED/CACHED</b> means a last-known-good value exists but is not fully fresh.</p>`));
 sections.push(helpSection('overview','OVERVIEW i GLOBAL model','OVERVIEW and the GLOBAL model',
 `<p>OVERVIEW sažima cijeli sustav. GLOBAL score koristi sljedeće ciljane težine: <b>Credit/Funding 25%</b>, <b>Volatility 15%</b>, <b>Equity 10%</b>, <b>Macro 15%</b>, <b>Liquidity 10%</b>, <b>Rates 8%</b>, <b>FX 7%</b>, <b>Commodities 5%</b> i <b>Correlation 5%</b>.</p><p>Ako neka kategorija nedostaje, ne dobiva score 0. Model računa rezultat iz preostalih dostupnih kategorija i smanjuje Coverage.</p><h5>Global snapshot</h5><ul><li><b>Contagion</b> — koliko se tržišta kreću zajedno i raste li sistemska povezanost.</li><li><b>Markets stressed</b> — broj tržišta u višim risk bandovima.</li><li><b>Top driver</b> — kategorija koja najviše doprinosi trenutnom riziku.</li><li><b>Data coverage</b> — udio dostupnih težina/signala.</li></ul><h5>Why is risk changing?</h5><p>Ovdje se uspoređuje trenutačni score s lokalnom poviješću/snapshotom i prikazuju najveće promjene. To je korisnije od samog ukupnog broja.</p>`,
 `<p>OVERVIEW summarizes the whole system. The GLOBAL score uses these target weights: <b>Credit/Funding 25%</b>, <b>Volatility 15%</b>, <b>Equity 10%</b>, <b>Macro 15%</b>, <b>Liquidity 10%</b>, <b>Rates 8%</b>, <b>FX 7%</b>, <b>Commodities 5%</b> and <b>Correlation 5%</b>.</p><p>If a category is missing, it does not receive a zero. The model computes from remaining valid categories and reduces Coverage.</p><h5>Global snapshot</h5><ul><li><b>Contagion</b> — how strongly markets are moving together and whether systemic linkage is rising.</li><li><b>Markets stressed</b> — number of markets in higher-risk bands.</li><li><b>Top driver</b> — the category contributing most to current risk.</li><li><b>Data coverage</b> — share of intended weights/signals currently available.</li></ul><h5>Why is risk changing?</h5><p>This compares the current score with local history/snapshots and highlights the largest changes. It is often more useful than the headline number alone.</p>`));
 sections.push(helpSection('markets','MARKETS, zemlje i Equity Internals','MARKETS, countries and Equity Internals',
 `<p>Svaka zemlja ima vlastiti composite. Zadane country težine su: <b>market 25</b>, <b>macro 20</b>, <b>credit 15</b>, <b>liquidity 15</b>, <b>valuation 10</b>, <b>technical 10</b>, <b>systemic 5</b>. U Settings ih možeš promijeniti.</p><table class="help-table"><tr><th>Sub-score</th><th>Kako čitati</th></tr><tr><td>Market</td><td>Trend, momentum, drawdown i volatilnost lokalnog indeksa.</td></tr><tr><td>Macro</td><td>Rast, inflacija, nezaposlenost i širi ciklički kontekst.</td></tr><tr><td>Credit</td><td>Financijski uvjeti i kreditni stres gdje postoje usporedivi podaci.</td></tr><tr><td>Liquidity</td><td>FX/financijska likvidnost i uvjeti financiranja.</td></tr><tr><td>Valuation</td><td>Procjena valuacijskog pritiska gdje je dostupna.</td></tr><tr><td>Technical</td><td>50/200DMA, trend i market structure.</td></tr><tr><td>Systemic</td><td>Širi sistemski/contagion signal.</td></tr></table><p><b>Equity Internals</b> traži slabost ispod headline indeksa: breadth, leadership, size participation, volatilnost i skrivene divergencije. Indeks može rasti dok većina komponenti slabi — to je važan early-warning obrazac.</p>`,
 `<p>Each country has its own composite. Default country weights are: <b>market 25</b>, <b>macro 20</b>, <b>credit 15</b>, <b>liquidity 15</b>, <b>valuation 10</b>, <b>technical 10</b>, <b>systemic 5</b>. You can change them in Settings.</p><table class="help-table"><tr><th>Sub-score</th><th>How to read it</th></tr><tr><td>Market</td><td>Trend, momentum, drawdown and volatility of the local index.</td></tr><tr><td>Macro</td><td>Growth, inflation, unemployment and broader cycle context.</td></tr><tr><td>Credit</td><td>Financial conditions and credit stress where comparable data exist.</td></tr><tr><td>Liquidity</td><td>FX/financial liquidity and funding conditions.</td></tr><tr><td>Valuation</td><td>Valuation pressure where available.</td></tr><tr><td>Technical</td><td>50/200DMA, trend and market structure.</td></tr><tr><td>Systemic</td><td>Broader systemic/contagion signal.</td></tr></table><p><b>Equity Internals</b> looks beneath the headline index: breadth, leadership, size participation, volatility and hidden divergence. An index can rise while most constituents weaken — that is an important early-warning pattern.</p>`));
 sections.push(helpSection('extended-countries','Extended 50 — dodatni country watch','Extended 50 — additional country watch',
 `<p>MARKETS stranica sadrži zaseban <b>Extended 50</b> sloj za još 50 gospodarski, financijski, energetski ili regionalno važnih država. Taj sloj koristi <b>World Bank World Development Indicators</b> za nominalni BDP, rast realnog BDP-a, inflaciju i nezaposlenost.</p><p>Podaci se učitavaju tek nakon otvaranja MARKETS taba i dohvaćaju se u nekoliko batch zahtjeva. Zemlje se zatim sortiraju prema najnovijem dostupnom nominalnom BDP-u.</p><div class="help-callout warn"><b>Važno:</b> Extended 50 je low-frequency macro watch. Ne ulazi u GLOBAL score, correlation matrix ili Equity Internals i ne predstavlja live trading signal.</div>`,
 `<p>The MARKETS page contains a separate <b>Extended 50</b> layer for 50 additional economies selected for economic, financial, energy/commodity or regional relevance. It uses <b>World Bank World Development Indicators</b> for nominal GDP, real-GDP growth, inflation and unemployment.</p><p>Data loads only after the MARKETS tab is opened and is retrieved through a small number of batched requests. Countries are then sorted by latest available nominal GDP.</p><div class="help-callout warn"><b>Important:</b> Extended 50 is a low-frequency macro watch. It does not enter the GLOBAL score, correlation matrix or Equity Internals and it is not a live trading signal.</div>`));
 sections.push(helpSection('early','EARLY — cross-asset i leading indikatori','EARLY — cross-asset and leading indicators',
 `<p>EARLY pokušava otkriti stres prije nego što se potpuno vidi u makro podacima ili headline indeksima. Tipične obitelji su <b>credit/funding</b>, <b>volatility</b>, <b>rates/yield curve</b>, <b>liquidity</b>, <b>systemic stress</b>, <b>breadth</b> i posebni regionalni moduli.</p><p>Najvažnije je tražiti <b>potvrdu</b>. VIX sam po sebi može skočiti kratkotrajno. VIX + širenje HY spreada + slabiji breadth + rast korelacija je znatno ozbiljniji obrazac.</p><div class="help-callout"><b>Pravilo:</b> jedan alarm = prati; više neovisnih alarma koji se kreću u istom smjeru = podigni oprez.</div>`,
 `<p>EARLY tries to identify stress before it is fully visible in macro data or headline indexes. Typical families include <b>credit/funding</b>, <b>volatility</b>, <b>rates/yield curve</b>, <b>liquidity</b>, <b>systemic stress</b>, <b>breadth</b> and special regional modules.</p><p>The key is <b>confirmation</b>. VIX alone can spike briefly. VIX + wider HY spreads + weaker breadth + rising correlations is a much more serious pattern.</p><div class="help-callout"><b>Rule:</b> one alarm = monitor; several independent alarms moving in the same direction = raise caution.</div>`));
 sections.push(helpSection('macro','MACRO — Inflation i Recession detector','MACRO — Inflation and Recession detectors',
 `<p>MACRO kombinira službene i tržišno-potvrđujuće podatke. <b>Inflation detector</b> koristi obitelji poput core CPI, core PCE, median/sticky inflacije, sheltera, plaća/labor, pipeline pritisaka, očekivanja i headline breadth-a. <b>Recession detector</b> koristi Sahm, yield curve, initial claims, nezaposlenost, payroll/hours, permits, SLOOS/credit, leading index i njemački ciklički signal.</p><p>Model razlikuje režime:</p><ul><li><b>STAGFLATION RISK</b> — inflation i recession score su oba ≥60.</li><li><b>INFLATION-DOMINANT</b> — inflacija ≥60, recesija ispod 60.</li><li><b>RECESSION-DOMINANT</b> — recesija ≥60, inflacija ispod 60.</li><li><b>DISINFLATIONARY SLOWDOWN</b> — recesijski rizik je povišen, dok je inflacijski nizak.</li><li><b>SOFT-LANDING / NORMAL</b> — oba su ispod približno 45.</li></ul><p>Makro podaci često imaju prirodan lag. Datum zadnje observacije je važan jednako kao i vrijednost.</p>`,
 `<p>MACRO combines official and market-confirming data. The <b>Inflation detector</b> uses families such as core CPI, core PCE, median/sticky inflation, shelter, wages/labor, pipeline pressure, expectations and headline breadth. The <b>Recession detector</b> uses Sahm, yield curve, initial claims, unemployment, payroll/hours, permits, SLOOS/credit, a leading index and German cyclical signals.</p><p>The model distinguishes regimes:</p><ul><li><b>STAGFLATION RISK</b> — both inflation and recession scores are ≥60.</li><li><b>INFLATION-DOMINANT</b> — inflation ≥60, recession below 60.</li><li><b>RECESSION-DOMINANT</b> — recession ≥60, inflation below 60.</li><li><b>DISINFLATIONARY SLOWDOWN</b> — recession risk is elevated while inflation risk is low.</li><li><b>SOFT-LANDING / NORMAL</b> — both are below roughly 45.</li></ul><p>Macro data naturally lag. The observation date matters as much as the value.</p>`));
 sections.push(helpSection('commodities','COMMOD — nafta, zlato, srebro i industrijski ciklus','COMMOD — oil, gold, silver and the industrial cycle',
 `<p>Commodity Risk Intelligence je <b>dijagnostički sloj</b>. Njegov vlastiti score nije izravno dodan kao novi GLOBAL score; GLOBAL već ima zasebnu 5% commodity komponentu kroz cross-asset model.</p><h5>Nafta</h5><ul><li><b>WTI/Brent</b> — cijena, momentum i volatilnost.</li><li><b>Commercial crude</b> — američke komercijalne zalihe.</li><li><b>SPR</b> — U.S. Strategic Petroleum Reserve, policy buffer, ne globalne geološke rezerve.</li><li><b>SPR fill</b> — trenutačni SPR u odnosu na autorizirani kapacitet.</li><li><b>Gasoline/Distillates/Days of supply</b> — dodatni supply/demand kontekst.</li></ul><h5>Zlato</h5><p>Prati se cijena, momentum, volatilnost i <b>kupnja centralnih banaka</b>. Snažna kupnja centralnih banaka sama po sebi nije signal recesije; važnija je kao potvrda reserve-diversification/safe-haven potražnje.</p><h5>Srebro i bakar</h5><p><b>Copper/Gold</b> je ciklički vs safe-haven signal. Pad omjera često znači da zlato nadmašuje industrijski bakar. Rast <b>Gold/Silver</b> može značiti da monetarno/safe-haven zlato nadmašuje industrijski osjetljivije srebro.</p><div class="help-callout warn"><b>Interpretacija:</b> rast nafte zbog supply šoka nije isto što i pad nafte zbog demand destructiona. Uvijek gledaj režim i ostale komponente.</div>`,
 `<p>Commodity Risk Intelligence is a <b>diagnostic layer</b>. Its own score is not directly added as a new GLOBAL score; GLOBAL already contains a separate 5% commodity component through the cross-asset model.</p><h5>Oil</h5><ul><li><b>WTI/Brent</b> — price, momentum and volatility.</li><li><b>Commercial crude</b> — U.S. commercial inventories.</li><li><b>SPR</b> — U.S. Strategic Petroleum Reserve, a policy buffer, not global geological reserves.</li><li><b>SPR fill</b> — current SPR relative to authorized capacity.</li><li><b>Gasoline/Distillates/Days of supply</b> — extra supply/demand context.</li></ul><h5>Gold</h5><p>The app tracks price, momentum, volatility and <b>central-bank buying</b>. Strong central-bank buying alone is not a recession signal; it is more useful as confirmation of reserve-diversification/safe-haven demand.</p><h5>Silver and copper</h5><p><b>Copper/Gold</b> is a cyclical-versus-safe-haven signal. A falling ratio often means gold is outperforming industrial copper. A rising <b>Gold/Silver</b> ratio can mean monetary/safe-haven gold is outperforming more industrially sensitive silver.</p><div class="help-callout warn"><b>Interpretation:</b> rising oil from a supply shock is not the same as falling oil from demand destruction. Always inspect the regime and other components.</div>`));
 sections.push(helpSection('sp500','S&P 500 i Hidden Weakness','S&P 500 and Hidden Weakness',
 `<p>S&amp;P tab sada sadrži svih 503 vrijednosnica koje predstavljaju 500 kompanija. Summary podaci se učitavaju tek kada otvoriš S&amp;P tab. Focus 100 ostaje stabilni uzorak samo za Hidden Weakness i sector breadth kako se ne bi mijenjala povijesna metodologija signala. Dostupno je sortiranje po najnižem RV20.</p><h5>Hidden Weakness %</h5><p>Postotak je <b>normalizirana snaga signala</b>, ne vjerojatnost pada. Detector kombinira 50/200DMA breadth, median 1M/3M momentum, broj slabih sektora, udio stressed kompanija, razliku S&amp;P indeksa prema median dionici i leadership koncentraciju mega-cap grupe.</p><table class="help-table"><tr><th>Signal</th><th>Tumačenje</th></tr><tr><td>&lt;25</td><td>Healthy participation / normalno.</td></tr><tr><td>25–44</td><td>WATCH — rane divergencije.</td></tr><tr><td>45–64</td><td>EARLY DIVERGENCE — oprez.</td></tr><tr><td>65–79</td><td>HIGH HIDDEN WEAKNESS — visok oprez.</td></tr><tr><td>≥80</td><td>SEVERE HIDDEN WEAKNESS — defenzivniji posture.</td></tr></table><p>Ako je učitano manje od <b>40%</b> focus-universea, app prikazuje WAIT FOR DATA. Ako je interna slabost već jaka, a headline indeks je više ne skriva, režim može postati <b>WEAKNESS ALREADY VISIBLE</b>.</p>`,
 `<p>The S&amp;P tab now contains all 503 securities representing 500 companies. Summary data load only after opening the S&amp;P tab. Focus 100 remains the stable sample only for Hidden Weakness and sector breadth so the historical signal methodology is not changed. Lowest-RV20 sorting is available.</p><h5>Hidden Weakness %</h5><p>The percentage is <b>normalized signal strength</b>, not crash probability. The detector combines 50/200DMA breadth, median 1M/3M momentum, weak-sector share, stressed-company share, the S&amp;P index versus the median stock, and mega-cap leadership concentration.</p><table class="help-table"><tr><th>Signal</th><th>Interpretation</th></tr><tr><td>&lt;25</td><td>Healthy participation / normal.</td></tr><tr><td>25–44</td><td>WATCH — early divergence.</td></tr><tr><td>45–64</td><td>EARLY DIVERGENCE — caution.</td></tr><tr><td>65–79</td><td>HIGH HIDDEN WEAKNESS — high caution.</td></tr><tr><td>≥80</td><td>SEVERE HIDDEN WEAKNESS — more defensive posture.</td></tr></table><p>If fewer than <b>40%</b> of the focus universe is loaded, the app shows WAIT FOR DATA. If internal weakness is already strong and the headline index is no longer hiding it, the regime can become <b>WEAKNESS ALREADY VISIBLE</b>.</p>`));
 sections.push(helpSection('stocks','Dionice i Company Risk Intelligence','Stocks and Company Risk Intelligence',
 `<p>Klik na dionicu tek tada učitava puni 5Y detail. <b>Company Core Risk</b> kombinira približno: momentum 40%, drawdown 25%, realized volatility 20% i technical trend 15%. Kontekstualni score zatim daje 70% core risku te po 15% relative strengthu prema zemlji i industriji.</p><ul><li><b>1M/3M/6M/1Y</b> — price momentum, ne total return.</li><li><b>52W/5Y drawdown</b> — pad od relevantnog vrha; veći negativni drawdown znači veći stres.</li><li><b>RV20/RV60</b> — annualized realized volatility; viša volatilnost = veći risk contribution.</li><li><b>50DMA/200DMA distance</b> — položaj cijene prema srednjoročnom/dugoročnom trendu.</li><li><b>Relative strength</b> — dionica prema lokalnom indeksu i peer industriji.</li></ul><p><b>Country/Industry Company Breadth</b> gleda koliko je ključnih kompanija iznad 50/200DMA, koliko ima pozitivan momentum i koliko outperformira benchmark. Viši breadth-risk score znači širu internu slabost.</p>`,
 `<p>Clicking a stock is what triggers the full 5Y detail load. <b>Company Core Risk</b> combines approximately: momentum 40%, drawdown 25%, realized volatility 20% and technical trend 15%. The contextual score then gives 70% to core risk and 15% each to relative strength versus country and industry.</p><ul><li><b>1M/3M/6M/1Y</b> — price momentum, not total return.</li><li><b>52W/5Y drawdown</b> — decline from the relevant high; a larger negative drawdown means more stress.</li><li><b>RV20/RV60</b> — annualized realized volatility; higher volatility raises risk contribution.</li><li><b>50DMA/200DMA distance</b> — price position versus medium/long-term trend.</li><li><b>Relative strength</b> — stock versus its local index and industry peers.</li></ul><p><b>Country/Industry Company Breadth</b> looks at how many key companies are above 50/200DMA, have positive momentum and outperform their benchmark. A higher breadth-risk score means broader internal weakness.</p>`));
 sections.push(helpSection('dividends','Dividend Intelligence i Dividend Safety','Dividend Intelligence and Dividend Safety',
 `<p>Dividendni podaci dolaze iz dostupnih market-data dividend events. Puni 5Y dividend history se učitava samo nakon klika na dionicu.</p><ul><li><b>TTM dividend yield</b> — zbroj dostupnih dividendi zadnjih 12 mjeseci / trenutna cijena.</li><li><b>12M dividend/share</b> — ukupna isplata po dionici u zadnjih 12 mjeseci.</li><li><b>3Y/5Y dividend CAGR</b> — trend rasta godišnjih isplata gdje ima dovoljno povijesti.</li><li><b>Growth years</b> — uzastopne pune godine rasta prema dostupnim eventima.</li><li><b>Cut history</b> — veliki godišnji rez definiran iz dostupnih isplata.</li></ul><p><b>Dividend Safety</b> je jedini važan score gdje <b>viši broj = bolje</b>: ≥80 HIGH, 65–79 GOOD, 45–64 MODERATE, &lt;45 LOW. Težine su približno: cut history 30%, growth 20%, consistency 20%, market risk 20%, yield quality 10%.</p><div class="help-callout warn"><b>Nije fundamentalni payout model.</b> Payout ratio i payment date se ne prikazuju kada feed nije dovoljno pouzdan. Ekstremno visok yield može smanjiti Safety jer može biti posljedica pada cijene ili očekivanog reza.</div>`,
 `<p>Dividend data come from available market-data dividend events. Full 5Y dividend history loads only after clicking a stock.</p><ul><li><b>TTM dividend yield</b> — sum of available dividends over the last 12 months / current price.</li><li><b>12M dividend/share</b> — total payout per share over the last 12 months.</li><li><b>3Y/5Y dividend CAGR</b> — trend in annual payouts where enough history exists.</li><li><b>Growth years</b> — consecutive complete years of growth based on available events.</li><li><b>Cut history</b> — major annual cuts derived from available payouts.</li></ul><p><b>Dividend Safety</b> is an important exception where <b>a higher score is better</b>: ≥80 HIGH, 65–79 GOOD, 45–64 MODERATE, &lt;45 LOW. Approximate weights are: cut history 30%, growth 20%, consistency 20%, market risk 20%, yield quality 10%.</p><div class="help-callout warn"><b>This is not a fundamental payout model.</b> Payout ratio and payment date are not shown when the feed is not reliable enough. An extremely high yield can reduce Safety because it may result from a falling share price or an expected cut.</div>`));
 sections.push(helpSection('etf','ETF Intelligence — ACC, DIST i ETF risk','ETF Intelligence — ACC, DIST and ETF risk',
 `<p>ETF tab se učitava lazy. Sažeci dolaze nakon otvaranja taba; puna 5Y povijest tek nakon klika.</p><ul><li><b>ACC / Accumulating</b> — prihod/dividende se reinvestiraju unutar fonda.</li><li><b>DIST / Distributing</b> — fond isplaćuje prihod investitoru.</li><li><b>NONE</b> — proizvod nema klasičnu dividendnu income politiku, npr. određeni fizički metalni trustovi.</li></ul><p><b>1Y price return</b> nije isto što i total return. Kod DIST fonda <b>trailing 12M cash yield</b> je približan omjer dostupnih dividendnih događaja i trenutne cijene. Kod ACC fonda cash yield nije usporediv jer se prihod reinvestira.</p><p>ETF risk koristi isti market-stress koncept kao company core risk: momentum, drawdown, volatilnost i tehnički trend. To nije ranking “najboljeg ETF-a” niti preporuka za kupnju.</p>`,
 `<p>The ETF tab loads lazily. Summaries load after opening the tab; full 5Y history only after a click.</p><ul><li><b>ACC / Accumulating</b> — income/dividends are reinvested inside the fund.</li><li><b>DIST / Distributing</b> — the fund pays income to the investor.</li><li><b>NONE</b> — the product has no conventional dividend-income policy, e.g. some physically backed metal trusts.</li></ul><p><b>1Y price return</b> is not the same as total return. For DIST funds, <b>trailing 12M cash yield</b> is an approximate ratio of available dividend events to current price. For ACC funds, cash yield is not comparable because income is reinvested.</p><p>ETF risk uses the same market-stress concept as company core risk: momentum, drawdown, volatility and technical trend. It is not a “best ETF” ranking or a buy recommendation.</p>`));
 sections.push(helpSection('corr','CORR — korelacije i contagion','CORR — correlations and contagion',
 `<p>Korelacija se računa iz <b>dnevnih povrata</b>, ne iz razine indeksa. r=+1 znači gotovo isto kretanje, r=-1 suprotno, r≈0 malo stabilne linearne veze.</p><table class="help-table"><tr><th>|r|</th><th>Snaga</th></tr><tr><td>&lt;0.20</td><td>LOW</td></tr><tr><td>0.20–0.49</td><td>NORMAL</td></tr><tr><td>0.50–0.74</td><td>HIGH</td></tr><tr><td>≥0.75</td><td>EXTREME</td></tr></table><p>Globalni correlation regime koristi prosjek parova: ispod 0.35 LOW, 0.35–0.54 NORMAL, 0.55–0.74 HIGH, ≥0.75 EXTREME.</p><p><b>Contagion</b> je posebno važan u stresu: geografski različita tržišta mogu odjednom postati jedan zajednički “risk asset”. Visoka korelacija sama po sebi ne dokazuje uzrok.</p>`,
 `<p>Correlation is calculated from <b>daily returns</b>, not index levels. r=+1 means almost the same movement, r=-1 opposite movement, r≈0 little stable linear relationship.</p><table class="help-table"><tr><th>|r|</th><th>Strength</th></tr><tr><td>&lt;0.20</td><td>LOW</td></tr><tr><td>0.20–0.49</td><td>NORMAL</td></tr><tr><td>0.50–0.74</td><td>HIGH</td></tr><tr><td>≥0.75</td><td>EXTREME</td></tr></table><p>The global correlation regime uses the pairwise average: below 0.35 LOW, 0.35–0.54 NORMAL, 0.55–0.74 HIGH, ≥0.75 EXTREME.</p><p><b>Contagion</b> matters especially in stress: geographically different markets can suddenly behave like one common “risk asset”. High correlation alone does not prove causality.</p>`));
 sections.push(helpSection('history','HISTORY — lokalna povijest i promjene statusa','HISTORY — local history and status changes',
 `<p>Aplikacija sprema približno <b>jedan lokalni snapshot po kalendarskom danu</b>. HISTORY zato nije intraday trading graf, nego zapis promjene risk režima kroz vrijeme.</p><p>Koristi ga za pitanja: raste li GLOBAL risk više dana, koja kategorija se pogoršava, je li alarm kratkotrajan ili trajan i je li contagion rastao zajedno s risk scoreom.</p><p>Brisanje aplikacijskih podataka/deinstalacija može ukloniti lokalnu povijest ako nije zasebno eksportirana.</p>`,
 `<p>The app stores approximately <b>one local snapshot per calendar day</b>. HISTORY is therefore not an intraday trading chart; it records changes in the risk regime over time.</p><p>Use it to ask: has GLOBAL risk risen for several days, which family is deteriorating, is an alarm temporary or persistent, and did contagion rise together with the risk score?</p><p>Clearing app data/uninstalling can remove local history unless it has been separately exported.</p>`));
 sections.push(helpSection('refresh','REFRESH, progressbar i lazy loading','REFRESH, progress bar and lazy loading',
 `<p><b>Ručni REFRESH</b> i pull-to-refresh forsiraju novi pokušaj prema live izvorima i zaobilaze normalni TTL cache gdje je moguće. Progressbar uvijek pokazuje koju fazu sustav obrađuje.</p><p><b>Automatski refresh</b> koristi Smart Refresh intervale kako ne bi nepotrebno opterećivao provider. Spori/rijetko promjenjivi makro izvori imaju duži TTL od tržišnih cijena.</p><p>Teški moduli nisu startup-blocking: S&amp;P 500 summaryji i ETF sažeci se učitavaju nakon otvaranja taba; 5Y stock/ETF/dividend detail tek nakon klika.</p><div class="help-callout"><b>Fresh attempt ≠ nova observacija.</b> CPI može biti uspješno osvježen, ali službeni podatak ostati isti jer novi mjesečni release još nije objavljen.</div>`,
 `<p><b>Manual REFRESH</b> and pull-to-refresh force a new attempt against live sources and bypass normal TTL cache where possible. The progress bar always shows which stage is being processed.</p><p><b>Automatic refresh</b> uses Smart Refresh intervals so providers are not polled unnecessarily. Slow/low-frequency macro sources have longer TTLs than market prices.</p><p>Heavy modules do not block startup: S&amp;P 500 summaries and ETF summaries load after opening their tab; 5Y stock/ETF/dividend detail only after a click.</p><div class="help-callout"><b>Fresh attempt ≠ new observation.</b> CPI can refresh successfully while the official value remains unchanged because the next monthly release has not yet been published.</div>`));
 sections.push(helpSection('sources','Data Sources, ONLINE/DEGRADED/CACHED/OFFLINE','Data Sources, ONLINE/DEGRADED/CACHED/OFFLINE',
 `<p>Settings → Data source health prikazuje stvarno runtime stanje na ovom uređaju.</p><ul><li><b>ONLINE</b> — provider ima uspješne live upite.</li><li><b>DEGRADED</b> — dio upita radi, dio ne radi.</li><li><b>CACHED</b> — live odgovor nije korišten, ali postoji valjan cache.</li><li><b>OFFLINE</b> — nema uspješnog live odgovora u trenutačnoj sesiji i nema primjenjivog fallbacka za taj request.</li></ul><p>Kvar jednog providera <b>ne bi trebao</b> poništiti druge kategorije. Npr. FRED problem ne bi smio oboriti Yahoo market cijene ili Cboe volatilnost.</p><p>Izvori imaju različitu kvalitetu i frekvenciju. Market data mogu biti delayed; službeni makro podaci mogu biti stari tjednima jer su mjesečni/kvartalni, a ipak su najnovija službena observacija.</p>`,
 `<p>Settings → Data source health shows actual runtime status on this device.</p><ul><li><b>ONLINE</b> — the provider has successful live requests.</li><li><b>DEGRADED</b> — some requests succeed and some fail.</li><li><b>CACHED</b> — a live response was not used, but a valid cache entry exists.</li><li><b>OFFLINE</b> — there is no successful live response in the current session and no applicable fallback for that request.</li></ul><p>A failure of one provider <b>should not</b> invalidate unrelated categories. For example, a FRED problem should not kill Yahoo market prices or Cboe volatility.</p><p>Sources have different quality and frequency. Market data may be delayed; official macro data may be weeks old because they are monthly/quarterly while still being the latest official observation.</p>`));
 sections.push(helpSection('energy-storage','Nafta, plin i grafikoni cijena','Oil, gas and price charts',
 `<h5>SAD — nafta</h5><p><b>SPR</b> se prikazuje kao trenutačna količina / službeni autorizirani kapacitet i <b>% popunjenosti</b>. Komercijalna sirova nafta, Cushing, benzin i destilati nemaju jedan usporediv službeni fiksni kapacitet, pa se za njih ne izmišlja fill %. Umjesto toga prikazuju se trenutačna razina te 7D i 1Y promjena.</p><h5>SAD — prirodni plin</h5><p>EIA working gas prikazuje se kao trenutačni Bcf / najnoviji službeni Total Working Gas Capacity i pripadajući postotak. Uz to se prikazuju tjedni injection/withdrawal, usporedba s prošlom godinom i 5-godišnjim prosjekom. Datum kapaciteta može biti stariji od tjedne stock opservacije.</p><h5>EU energija</h5><p>EU Gas koristi GIE AGSI+ i sada uključuje najveće facility-level skladišne datasetove. EU Oil je uklonjen iz ovog standalone releasea jer Eurostat transport nije bio dovoljno pouzdan u stvarno instaliranom Android/WebView build-u.</p><h5>Cijene</h5><p>WTI/Brent, Henry Hub, Gold i Silver prikazuju stvarnu povijest <b>cijene</b> kroz 1M/3M/1Y grafove, uz trenutačnu cijenu, povrat odabranog perioda i low/high raspon. Nedostajući datumi se ne pretvaraju u sintetičke cijene.</p><div class="help-callout warn"><b>Ne čitaj izolirano:</b> sama količina nije dovoljna. Za skladišta koristi službeni nazivnik i postotak popunjenosti; za cijene gledaj smjer i raspon kroz vrijeme.</div>`,
 `<h5>U.S. — oil</h5><p><b>SPR</b> is shown as current stock / official authorized capacity and <b>fill %</b>. Commercial crude, Cushing, gasoline and distillates do not share one comparable official fixed-capacity denominator, so the app does not fabricate a fill %. Instead it shows the current level plus 7D and 1Y change.</p><h5>U.S. — natural gas</h5><p>EIA working gas is shown as current Bcf / latest official Total Working Gas Capacity and the resulting percentage. Weekly injection/withdrawal, year-ago and 5-year-average comparisons are also shown. The capacity observation may be older than the weekly stock observation.</p><h5>EU energy</h5><p>EU Gas uses GIE AGSI+ and now includes the largest facility-level storage datasets. EU Oil is removed from this standalone release because Eurostat transport was not sufficiently reliable in the actually installed Android/WebView build.</p><h5>Prices</h5><p>WTI/Brent, Henry Hub, Gold and Silver use actual <b>price</b> history with 1M/3M/1Y charts, current price, selected-period return and low/high range. Missing dates are not turned into synthetic prices.</p><div class="help-callout warn"><b>Do not read in isolation:</b> an amount alone is not enough. For storage use an official denominator and fill percentage; for prices inspect direction and range over time.</div>`));
sections.push(helpSection('settings','SETTINGS — jezici, weights, alerts i appearance','SETTINGS — languages, weights, alerts and appearance',
 `<p><b>Language</b> mijenja UI. Ovaj detaljni Help je potpuno održavan na <b>engleskom i hrvatskom</b>; unutar Help prozora možeš ga ručno prebaciti EN/HR bez promjene cijelog UI-ja.</p><p><b>Country risk weights</b> mijenjaju samo country composite metodologiju. Ne mijenjaj ih često ako želiš usporedivu povijest. Težine se normaliziraju preko dostupnih sub-scoreova.</p><p><b>Risk alerts</b> uključuju in-app alert logiku; sistemske Android notifikacije ovise o dozvolama i build mogućnostima.</p><p><b>Appearance</b> mijenja light/dark/system izgled, ne risk model.</p>`,
 `<p><b>Language</b> changes the UI. This detailed Help is fully maintained in <b>English and Croatian</b>; inside Help you can switch EN/HR without changing the whole UI.</p><p><b>Country risk weights</b> change only the country-composite methodology. Avoid changing them frequently if you want comparable history. Weights are renormalized across available sub-scores.</p><p><b>Risk alerts</b> enable in-app alert logic; system Android notifications depend on permissions and build capabilities.</p><p><b>Appearance</b> changes light/dark/system presentation, not the risk model.</p>`));
 sections.push(helpSection('workflow','Praktičan workflow tumačenja','Practical interpretation workflow',
 `<ol><li><b>GLOBAL:</b> provjeri score + Coverage + Confidence.</li><li><b>Drivers:</b> identificiraj 2–3 najjače risk kategorije.</li><li><b>Confirmation:</b> traži potvrdu u EARLY, MACRO, CORR i COMMOD.</li><li><b>Breadth:</b> za SAD pogledaj Hidden Weakness; za zemlju/industriju Company Breadth.</li><li><b>Instrument:</b> tek zatim otvori dionicu ili ETF i pogledaj momentum, drawdown, volatilnost i relative strength.</li><li><b>Income:</b> ako te zanimaju dividende, odvoji Dividend Safety od market-risk scorea.</li><li><b>Freshness:</b> prije odluke provjeri Data source health i datum observacije.</li></ol><div class="help-callout good"><b>Najkorisniji obrazac:</b> Credit/Funding ↑ + Volatility ↑ + Breadth ↓ + Correlation ↑ + recession confirmation = znatno jači risk-off signal nego bilo koji od tih indikatora sam.</div>`,
 `<ol><li><b>GLOBAL:</b> check score + Coverage + Confidence.</li><li><b>Drivers:</b> identify the 2–3 strongest risk families.</li><li><b>Confirmation:</b> look for confirmation in EARLY, MACRO, CORR and COMMOD.</li><li><b>Breadth:</b> for the U.S. inspect Hidden Weakness; for a country/industry inspect Company Breadth.</li><li><b>Instrument:</b> only then open a stock or ETF and inspect momentum, drawdown, volatility and relative strength.</li><li><b>Income:</b> if dividends matter, separate Dividend Safety from market-risk score.</li><li><b>Freshness:</b> before acting, check Data source health and observation dates.</li></ol><div class="help-callout good"><b>Most useful pattern:</b> Credit/Funding ↑ + Volatility ↑ + Breadth ↓ + Correlation ↑ + recession confirmation = a much stronger risk-off signal than any one of those indicators alone.</div>`));
 sections.push(helpSection('limits','Što aplikacija NE govori','What the app does NOT tell you',
 `<ul><li>Ne predviđa točan datum market crasha.</li><li>Risk score nije statistička vjerojatnost pada.</li><li>Ne zamjenjuje fundamentalnu analizu kompanije.</li><li>Dividend Safety nije garancija buduće dividende.</li><li>Korelacija nije uzročnost.</li><li>Price return nije isto što i total return.</li><li>N/A nije isto što i nizak rizik.</li><li>Javni/best-effort feedovi nisu Bloomberg/Refinitiv razina tržišnih podataka.</li></ul><p>Aplikaciju koristi kao <b>decision-support / early-warning</b> alat: za disciplinirano praćenje promjene režima i potvrde između više tržišnih sustava.</p>`,
 `<ul><li>It does not predict the exact date of a market crash.</li><li>A risk score is not a statistical probability of decline.</li><li>It does not replace company fundamental analysis.</li><li>Dividend Safety is not a guarantee of future dividends.</li><li>Correlation is not causation.</li><li>Price return is not the same as total return.</li><li>N/A is not the same as low risk.</li><li>Public/best-effort feeds are not Bloomberg/Refinitiv-grade market data.</li></ul><p>Use the app as a <b>decision-support / early-warning</b> tool: disciplined monitoring of regime change and confirmation across multiple market systems.</p>`));
 return `<div class="help-toolbar"><div class="help-lang"><button class="seg help-lang-btn ${helpLanguage()==='en'?'active':''}" data-help-lang="en">EN</button><button class="seg help-lang-btn ${helpLanguage()==='hr'?'active':''}" data-help-lang="hr">HR</button></div><input id="helpSearch" class="help-search" type="search" placeholder="${esc(HH('Pretraži pomoć…','Search help…'))}" autocomplete="off"></div><div class="help-intro"><b>${esc(HH('Kako koristiti ovaj vodič','How to use this guide'))}:</b> ${esc(HH('Otvori temu ili upiši pojam poput VIX, Coverage, dividenda, ETF, nafta, correlation ili Hidden Weakness. Help ne pokreće mrežne zahtjeve i ne utječe na risk model.','Open a topic or search for a term such as VIX, Coverage, dividend, ETF, oil, correlation or Hidden Weakness. Help makes no network requests and does not affect the risk model.'))}</div><div class="help-topics">${sections.join('')}</div>`;
}
function filterHelp(q){let query=String(q||'').trim().toLocaleLowerCase();document.querySelectorAll('#helpModalBody .help-topic').forEach(el=>{let hit=!query||el.textContent.toLocaleLowerCase().includes(query);el.style.display=hit?'':'none';if(query&&hit)el.open=true})}
function renderHelp(){let body=$('helpModalBody');if(!body)return;$('helpModalTitle').textContent=HH('Pomoć i tumačenje','Help & interpretation');$('closeHelpModal').textContent=HH('NATRAG','BACK');body.innerHTML=helpHtml();let s=$('helpSearch');if(s)s.oninput=e=>filterHelp(e.target.value);document.querySelectorAll('.help-lang-btn').forEach(b=>b.onclick=()=>{helpLangOverride=b.dataset.helpLang;renderHelp()})}
function openHelp(pushRoute=true){helpLangOverride=(currentLang==='hr'?'hr':'en');renderHelp();$('helpModal').classList.add('show');$('helpModal').scrollTop=0;if(pushRoute&&location.hash!=='#help'){rememberOriginState();history.pushState({mrmHelp:true,page:activePageId(),scrollY:Math.round(window.scrollY||0)},'','#help')}}
function closeHelp(){if(location.hash==='#help'){history.back();return}$('helpModal').classList.remove('show')}

function agsiSettingsStatusText(){let configured=agsiKeyConfigured(),mode=agsiStorageMode();if(!configured)return L('Nije konfigurirano','Not configured');return mode==='ANDROID_KEYSTORE'?L('Konfigurirano · Android Keystore','Configured · Android Keystore'):L('Konfigurirano · lokalna WebView pohrana','Configured · local WebView storage')}
function updateAgsiSettingsUi(extra=''){let el=$('agsiKeyStatus');if(el)el.textContent=agsiSettingsStatusText()+(extra?' · '+extra:'');let rm=$('clearAgsiKeyBtn');if(rm)rm.disabled=!agsiKeyConfigured()}
async function saveAndTestAgsiKey(){let input=$('agsiApiKeyInput'),raw=input?input.value:'';if(!agsiSaveKey(raw)){updateAgsiSettingsUi(L('Nevažeći format ključa','Invalid key format'));return}if(input)input.value='';updateAgsiSettingsUi(L('Provjeravam…','Testing…'));try{let d=await ensureEuGasV33(true,false);let obs=d&&d.current&&d.current.d?d.current.d:'—';updateAgsiSettingsUi(L('POVEZANO','CONNECTED')+' · '+L('opservacija','observation')+' '+obs);renderCommodities()}catch(e){let m=e&&e.message==='AGSI_INVALID_API_KEY'?L('NEVAŽEĆI KLJUČ','INVALID KEY'):L('GREŠKA VEZE','CONNECTION ERROR');updateAgsiSettingsUi(m)}}
async function testAgsiKey(){if(!agsiKeyConfigured()){updateAgsiSettingsUi(L('Prvo spremi ključ','Save a key first'));return}updateAgsiSettingsUi(L('Provjeravam…','Testing…'));try{let d=await ensureEuGasV33(true,false);updateAgsiSettingsUi(L('POVEZANO','CONNECTED')+' · '+L('opservacija','observation')+' '+(d&&d.current?d.current.d:'—'))}catch(e){updateAgsiSettingsUi(e&&e.message==='AGSI_INVALID_API_KEY'?L('NEVAŽEĆI KLJUČ','INVALID KEY'):L('GREŠKA VEZE','CONNECTION ERROR'))}}
function clearAgsiKeyFromSettings(){agsiClearKey();let input=$('agsiApiKeyInput');if(input)input.value='';updateAgsiSettingsUi(L('Uklonjeno','Removed'));renderCommodities()}
function openAgsiSettings(){navTo('settings');setTimeout(()=>{let x=$('agsiApiKeyInput');if(x){x.scrollIntoView({behavior:'smooth',block:'center'});x.focus()}},80)}
// v3.5.1.47 — local audit exports. Presentation/data-governance only; no network requests.
const EXPORT_V47_VERSION='3.5.1.50',EXPORT_V47_CODE=83;
const EXPORT_SECRET_KEY_V47=/(?:api[_-]?key|apikey|token|authorization|password|secret|cookie|x-key|access[_-]?token)/i;
function sanitizeExportV47(value,seen=new WeakSet()){if(value===null||value===undefined)return value;if(typeof value==='function'||typeof value==='symbol')return undefined;if(typeof value!=='object')return value;if(seen.has(value))return'[Circular]';seen.add(value);if(Array.isArray(value))return value.map(x=>sanitizeExportV47(x,seen)).filter(x=>x!==undefined);let out={};for(const [k,v] of Object.entries(value)){if(EXPORT_SECRET_KEY_V47.test(k))continue;if(v&&typeof v.then==='function')continue;let clean=sanitizeExportV47(v,seen);if(clean!==undefined)out[k]=clean}return out}
function exportTimestampV47(){return new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z')}
function csvCellV47(v){if(v===null||v===undefined)return'';let x=typeof v==='object'?JSON.stringify(v):String(v);return /[",\n\r]/.test(x)?'"'+x.replace(/"/g,'""')+'"':x}
function csvV47(rows,cols){let keys=cols||[...new Set((rows||[]).flatMap(r=>Object.keys(r||{})))];return '\ufeff'+[keys.join(','),...(rows||[]).map(r=>keys.map(k=>csvCellV47(r&&r[k])).join(','))].join('\r\n')+'\r\n'}
function marketAuditRowsV47(){return (appState.countries||[]).filter(c=>c).map(c=>{let ser=Array.isArray(c.series)?c.series.filter(x=>x&&Number.isFinite(Number(x.v))):[],first=ser[0]||null,last=ser.at(-1)||null,eq=c.equityInternals||appState.equity&&appState.equity.byCode&&appState.equity.byCode[c.code]||null,fr=fiscalV43&&fiscalV43.byCode&&fiscalV43.byCode[c.code]||null,cv=c.coverageV50||{};return{countryCode:c.code,country:c.name,index:c.index,symbol:c.symbol||'',provider:c.provider||c.quality&&c.quality.source||'',latestValue:c.metrics&&c.metrics.value,priceChange1d:c.metrics&&c.metrics.d1,observationTimestamp:c.quality&&c.quality.date,historyStart:first&&(first.d||first.date||first.t),historyEnd:last&&(last.d||last.date||last.t),historyObservations:ser.length,marketScore:c.subscores&&c.subscores.market,macroScore:c.subscores&&c.subscores.macro,liquidityScore:c.subscores&&c.subscores.liquidity,technicalScore:c.subscores&&c.subscores.technical,internalsScore:eq&&eq.score,fiscalScore:fr&&fr.score,fiscalStatus:fr&&fr.band&&fr.band.regime,finalCountryScore:c.risk,riskBand:c.limited?'LIMITED DATA':Number.isFinite(c.risk)?riskBand(c.risk).label:'LIMITED DATA',dataCoverage:cv.dataCoverage,factorCoverage:cv.factorCoverage,freshnessCoverage:cv.freshnessCoverage,effectiveWeightedCoverage:cv.effectiveWeightedCoverage,factorGroups:cv.factorGroups,eligibility:cv.eligible,eligibilityReason:cv.reason,limitedData:!!c.limited||!c.metrics,marketHealthEligible:eq?equityGlobalEligibilityV42(c,eq):false,source:c.quality&&c.quality.source,freshness:c.quality&&c.quality.freshness,retrievedAt:c.quality&&c.quality.retrievedAt}})}
function fiscalAuditRowsV47(){return (fiscalV43&&fiscalV43.rows||[]).filter(r=>r).map(r=>{let ref=r.references&&r.references.debt||null,refs=r.references||{};return{countryCode:r.code,country:r.name,provider:(r.providers||[]).join(' | '),seriesId:ref&&ref.indicator||ref&&ref.seriesId||'',metricDefinition:r.definition||ref&&ref.definition||'',debtGdp:r.raw&&r.raw.debt,debtTrend:r.raw&&r.raw.debtTrend,fiscalBalance:r.raw&&r.raw.balance,primaryBalance:r.raw&&r.raw.primary,interestBurden:r.raw&&r.raw.interest,sovereignYield:r.raw&&r.raw.yield,spreadBps:r.raw&&r.raw.spreadBps,averageDebtCost:r.raw&&r.raw.effectiveRate,refinancingGap:r.raw&&r.raw.refiGap,rMinusG:r.raw&&r.raw.rMinusG,debtReference:refs.debt&&fiscalRefLabelV44(refs.debt)||'',balanceReference:refs.balance&&fiscalRefLabelV44(refs.balance)||'',interestReference:refs.interest&&fiscalRefLabelV44(refs.interest)||'',yieldReference:refs.yield&&fiscalRefLabelV44(refs.yield)||'',observationDate:ref&&ref.observation||'',retrievalDate:r.retrievedAt||(fiscalV43.loadedAt?new Date(fiscalV43.loadedAt).toISOString():''),frequency:ref&&ref.frequency||'',valueType:ref&&ref.valueType||'',freshness:ref&&ref.freshness||'',comparability:r.comparability||'',eligibleForScore:Number.isFinite(r.score)&&!(r.staleMetrics||[]).length,exclusionReason:(r.staleMetrics||[]).length?'STALE: '+r.staleMetrics.join('|'):(r.comparability==='COMPARABILITY LIMITED'?'COMPARABILITY LIMITED':''),coverage:r.coverage,coverageTier:r.coverageTier,score:r.score,status:r.band&&r.band.regime,drivers:r.drivers,offsets:r.offsets,rankingEligible:!!r.rankingEligible}})}
function macroAuditRowsV47(){let m=appState.macroCycle||{},out=[];for(const [family,obj] of [['inflation',m.inflation],['recession',m.recession]])for(const r of obj&&obj.rows||[])out.push({family,indicator:r.name,countryRegion:r.country||r.region||'US/Global',provider:r.provider||r.source||'',seriesId:r.id||r.seriesId||'',rawValue:r.value,transformedValue:r.score,unit:r.unit||'',observationDate:r.date||r.observationDate||'',retrievedAt:r.retrievedAt||'',frequency:r.dataKind||'',releaseDate:r.releaseDate||'',expectedNextRelease:r.expectedNextRelease||'',observationAge:r.observationAge,releaseStatus:r.releaseStatus||'',freshness:r.freshness||'',confidence:r.confidence||'',contribution:r.score});return out}
