function v19IsoDaysAgo(days){let d=new Date();d.setUTCDate(d.getUTCDate()-days);return d.toISOString().slice(0,10)}
function v19Num(v){let n=typeof v==='number'?v:Number(String(v??'').replace(/,/g,'').trim());return Number.isFinite(n)?n:null}
function v19Signed(v,d=1,suffix=''){return Number.isFinite(v)?((v>0?'+':'')+fmt(v,d)+suffix):'—'}
