function v20Compare(series,days){if(!v20ValidSeries(series,2))return null;let last=series.at(-1),target=new Date(last.d+'T12:00:00Z');target.setUTCDate(target.getUTCDate()-days);let p=indexAtOrBefore(series,target.toISOString().slice(0,10));if(!Number.isFinite(p)||!last||!Number.isFinite(last.v)||p===0)return null;return{abs:last.v-p,pct:p!==0?100*(last.v-p)/p:null,base:p,last:last.v}}
async function agsiApiJsonV33(url,force=false){if(!agsiKeyConfigured())throw new Error('AGSI_API_KEY_REQUIRED');if(location.hostname==='app.local'&&hasNativeAgsiSecretStore())return fetchWithTimeout(url,'json',16000,true,force);let key=agsiFallbackKey();if(!key)throw new Error('AGSI_API_KEY_REQUIRED');let ck=AGSI_LOCAL_CACHE_PREFIX+cacheHash(url),ttl=6*60*60*1000,now=Date.now(),cached=null;try{cached=JSON.parse(safeGet(ck)||'null')}catch(_){cached=null}if(!force&&cached&&cached.ts&&now-cached.ts<ttl&&cached.data){recordProviderCache(url,now-cached.ts,false);return cached.data}let ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),16000),started=performance.now(),recorded=false;try{let r=await fetch(url,{cache:'no-store',signal:ctrl.signal,headers:{'Accept':'application/json','x-key':key}}),lat=Math.round(performance.now()-started);if(!r.ok)throw new Error(r.status===401||r.status===403?'AGSI_INVALID_API_KEY':'HTTP '+r.status);let data=await r.json();if(data&&data.error)throw new Error(/access denied/i.test(String(data.error))?'AGSI_INVALID_API_KEY':'GIE: '+data.error);safeSet(ck,JSON.stringify({ts:Date.now(),data}));recordProvider(url,true,lat);recorded=true;return data}catch(e){if(!force&&cached&&cached.data){recordProviderCache(url,now-(cached.ts||0),true);return cached.data}if(!recorded)recordProvider(url,false,Math.round(performance.now()-started),e&&e.message||'AGSI request failed');throw e}finally{clearTimeout(timer)}}
function parseAgsiPayloadV33(j){if(j&&typeof j==='object'&&j.error)throw new Error(/access denied|api.?key|unauthor/i.test(String(j.error))?'AGSI_INVALID_API_KEY':'GIE: '+j.error);if(!j||typeof j!=='object'||!Array.isArray(j.data))throw new Error('GIE AGSI JSON is empty or unrecognized');let rows=[];for(const x of j.data){if(!x||typeof x!=='object')continue;let d=String(x.gasDayStart||x.gas_day||'').slice(0,10),stock=v19Num(x.gasInStorage),cap=v19Num(x.workingGasVolume),fill=v19Num(x.full);if(!/^20\d\d-\d\d-\d\d$/.test(d)||!Number.isFinite(stock)||!Number.isFinite(cap)||cap<=0)continue;if(!Number.isFinite(fill))fill=100*stock/cap;let injection=v19Num(x.injection),withdrawal=v19Num(x.withdrawal),netWithdrawal=v19Num(x.netWithdrawal),netFlow=Number.isFinite(injection)&&Number.isFinite(withdrawal)?injection-withdrawal:(Number.isFinite(netWithdrawal)?-netWithdrawal:null);rows.push({d,stock,capacity:cap,fill,injection,withdrawal,netFlow,status:String(x.status||''),trend:v19Num(x.trend)})}if(!rows.length)throw new Error('GIE AGSI storage observations not found');rows.sort((a,b)=>a.d.localeCompare(b.d));let uniq=new Map();for(const r of rows){let old=uniq.get(r.d);if(!old||old.status!=='C'||r.status==='C')uniq.set(r.d,r)}return{rows:[...uniq.values()].sort((a,b)=>a.d.localeCompare(b.d)),lastPage:Math.max(1,Number(j.last_page)||1),dataset:String(j.dataset||'EU'),gasDay:String(j.gas_day||'').slice(0,10)}}
