function metalHtmlV32(kind){let base=metalHtmlV19(kind),d=commodityV32.overview.data,a=d&&d.analytics&&d.analytics[kind];let extra=a?`<div class="section-title">${esc(L('Risk intelligence','Risk intelligence'))}</div><div class="commodity-grid">${c32AnalyticsCards(a)}</div>`:'';if(kind==='gold'&&d&&d.goldSilver){let g=d.goldSilver;extra+=`<div class="section-title">Gold / Silver</div><div class="commodity-grid">${commodityMetricCard(L('Trenutni omjer','Current ratio'),Number.isFinite(g.value)?fmt(g.value,2):'—',g.date||'')}${commodityMetricCard('1M',Number.isFinite(g.m1)?v19Signed(g.m1,1,'%'):'—','')}${commodityMetricCard('3M',Number.isFinite(g.m3)?v19Signed(g.m3,1,'%'):'—','')}${commodityMetricCard(L('Povijesni percentil','Historical percentile'),Number.isFinite(g.returnPercentile)?fmt(g.returnPercentile,0)+'%':'—',L('3M promjena omjera','3M ratio change'),'',g.returnPercentile,'percentile')}</div>`}if(kind==='gold')extra+=goldContextHtmlV32();return extra+base}
function commoditySubnavV19(){let tabs=[['overview',L('Pregled','Overview')],['usOil',L('SAD nafta','US Oil')],['usGas',L('SAD plin','US Gas')],['euGas',L('EU plin','EU Gas')],['gold',L('Zlato','Gold')],['silver',L('Srebro','Silver')],['food',L('Hrana','Food')]];return `<div class="controls commodity-v19-nav" style="margin-bottom:10px">${tabs.map(([k,n])=>`<button class="seg ${commodityViewV19===k?'active':''}" data-commodity-v19="${k}">${esc(n)}</button>`).join('')}</div>`}
