function fiscalUniverseV43(){let m=new Map(),add=x=>{if(!x||!x.code||!x.iso)return;let old=m.get(x.code)||{};m.set(x.code,{...old,...x,eu:!!(old.eu||x.eu)})};FISCAL_EU27_V43.forEach(add);FISCAL_MANDATORY_GLOBAL_V43.forEach(add);[...MARKET_CONFIG,...EXTENDED_COUNTRY_CONFIG].forEach(add);return [...m.values()].map(x=>({...x,region:x.region||(x.eu?'Europe':'Other')}))}
