function fiscalBandV43(score){if(!Number.isFinite(score))return{label:L('OGRANIČENI PODACI','LIMITED DATA'),short:'LIMITED',cls:'status-limited',regime:'LIMITED DATA'};if(score<35)return{label:L('NORMALNO','NORMAL'),short:'GREEN',cls:'status-green',regime:'NORMAL'};if(score<50)return{label:L('PRATI','WATCH'),short:'YELLOW',cls:'status-yellow',regime:'WATCH'};if(score<70)return{label:L('POVIŠENO','ELEVATED'),short:'ORANGE',cls:'status-orange',regime:'ELEVATED'};return{label:L('VISOK STRES','HIGH STRESS'),short:'RED',cls:'status-red',regime:'HIGH STRESS'}}
